package ibex_pkg;

  // ---------------
  // RV32M parameter
  // ---------------
  typedef enum logic {
    RV32MFast         = 1'b0,
    RV32MSingleCycle  = 1'b1
  } rv32m_e;

  // ---------------
  // RV32B parameter
  // ---------------
  typedef enum logic [1:0] {
    RV32BNone      = 2'b00,
    RV32BBalanced  = 2'b01,
    RV32BOTEarlGrey = 2'b10,
    RV32BFull      = 2'b11
  } rv32b_e;

  // ---------------
  // RV32ZC parameter
  // ---------------
  typedef enum logic [1:0] {
    RV32Zca       = 2'b00,
    RV32ZcaZcb    = 2'b01,
    RV32ZcaZcbZcmp = 2'b10
  } rv32zc_e;

  // --------------------------
  // Register file type
  // --------------------------
  typedef enum logic [1:0] {
    RegFileFF    = 2'b00,
    RegFileFPGA  = 2'b01,
    RegFileLatch = 2'b10
  } regfile_e;

  // ---------------
  // CSR operations
  // ---------------
  typedef enum logic [1:0] {
    CSR_OP_READ  = 2'b00,
    CSR_OP_WRITE = 2'b01,
    CSR_OP_SET   = 2'b10,
    CSR_OP_CLEAR = 2'b11
  } csr_op_e;

  // ---------------
  // CSR addresses
  // ---------------
  typedef enum logic [11:0] {
    // Machine Information
    CSR_MVENDORID  = 12'hF11,
    CSR_MARCHID    = 12'hF12,
    CSR_MIMPID     = 12'hF14,
    CSR_MHARTID    = 12'hF14,

    // Machine Status
    CSR_MSTATUS    = 12'h300,
    CSR_MISA       = 12'h301,
    CSR_MIE        = 12'h304,
    CSR_MTVEC      = 12'h305,
    CSR_MCOUNTEREN = 12'h306,

    // Machine Trap Handling
    CSR_MSCRATCH   = 12'h340,
    CSR_MEPC       = 12'h341,
    CSR_MCAUSE     = 12'h342,
    CSR_MTVAL      = 12'h343,
    CSR_MIP        = 12'h344,

    // RISC-V Privileged Spec v1.11: mcounteren was removed, mcountinhibit added
    CSR_MCOUNTINHIBIT = 12'h320,

    // Machine Performance Monitoring Event Selectors
    CSR_MHPMEVENT3   = 12'h323,
    CSR_MHPMEVENT4   = 12'h324,
    CSR_MHPMEVENT5   = 12'h325,
    CSR_MHPMEVENT6   = 12'h326,
    CSR_MHPMEVENT7   = 12'h327,
    CSR_MHPMEVENT8   = 12'h328,
    CSR_MHPMEVENT9   = 12'h329,
    CSR_MHPMEVENT10  = 12'h32A,
    CSR_MHPMEVENT11  = 12'h32B,
    CSR_MHPMEVENT12  = 12'h32C,
    CSR_MHPMEVENT13  = 12'h32D,
    CSR_MHPMEVENT14  = 12'h32E,
    CSR_MHPMEVENT15  = 12'h32F,
    CSR_MHPMEVENT16  = 12'h330,
    CSR_MHPMEVENT17  = 12'h331,
    CSR_MHPMEVENT18  = 12'h332,
    CSR_MHPMEVENT19  = 12'h333,
    CSR_MHPMEVENT20  = 12'h334,
    CSR_MHPMEVENT21  = 12'h335,
    CSR_MHPMEVENT22  = 12'h336,
    CSR_MHPMEVENT23  = 12'h337,
    CSR_MHPMEVENT24  = 12'h338,
    CSR_MHPMEVENT25  = 12'h339,
    CSR_MHPMEVENT26  = 12'h33A,
    CSR_MHPMEVENT27  = 12'h33B,
    CSR_MHPMEVENT28  = 12'h33C,
    CSR_MHPMEVENT29  = 12'h33D,
    CSR_MHPMEVENT30  = 12'h33E,
    CSR_MHPMEVENT31  = 12'h33F,

    // PMP Configuration
    CSR_PMPCFG0    = 12'h3A0,
    CSR_PMPCFG1    = 12'h3A1,
    CSR_PMPCFG2    = 12'h3A2,
    CSR_PMPCFG3    = 12'h3A3,

    // PMP Address
    CSR_PMPADDR0   = 12'h3B0,
    CSR_PMPADDR1   = 12'h3B1,
    CSR_PMPADDR2   = 12'h3B2,
    CSR_PMPADDR3   = 12'h3B3,
    CSR_PMPADDR4   = 12'h3B4,
    CSR_PMPADDR5   = 12'h3B5,
    CSR_PMPADDR6   = 12'h3B6,
    CSR_PMPADDR7   = 12'h3B7,
    CSR_PMPADDR8   = 12'h3B8,
    CSR_PMPADDR9   = 12'h3B9,
    CSR_PMPADDR10  = 12'h3BA,
    CSR_PMPADDR11  = 12'h3BB,
    CSR_PMPADDR12  = 12'h3BC,
    CSR_PMPADDR13  = 12'h3BD,
    CSR_PMPADDR14  = 12'h3BE,
    CSR_PMPADDR15  = 12'h3BF,

    // Ibex custom CSRs
    CSR_CPUCTRL    = 12'h7C0,
    CSR_SECURESEED = 12'h7C1,
    CSR_MSECCFG    = 12'h747,
    CSR_MSECCFGH   = 12'h757,

    // Machine Counters/Timers (low)
    CSR_MCYCLE     = 12'hB00,
    CSR_MINSTRET   = 12'hB02,
    CSR_MHPMCOUNTER3  = 12'hB03,
    CSR_MHPMCOUNTER4  = 12'hB04,
    CSR_MHPMCOUNTER5  = 12'hB05,
    CSR_MHPMCOUNTER6  = 12'hB06,
    CSR_MHPMCOUNTER7  = 12'hB07,
    CSR_MHPMCOUNTER8  = 12'hB08,
    CSR_MHPMCOUNTER9  = 12'hB09,
    CSR_MHPMCOUNTER10 = 12'hB0A,
    CSR_MHPMCOUNTER11 = 12'hB0B,
    CSR_MHPMCOUNTER12 = 12'hB0C,
    CSR_MHPMCOUNTER13 = 12'hB0D,
    CSR_MHPMCOUNTER14 = 12'hB0E,
    CSR_MHPMCOUNTER15 = 12'hB0F,
    CSR_MHPMCOUNTER16 = 12'hB10,
    CSR_MHPMCOUNTER17 = 12'hB11,
    CSR_MHPMCOUNTER18 = 12'hB12,
    CSR_MHPMCOUNTER19 = 12'hB13,
    CSR_MHPMCOUNTER20 = 12'hB14,
    CSR_MHPMCOUNTER21 = 12'hB15,
    CSR_MHPMCOUNTER22 = 12'hB16,
    CSR_MHPMCOUNTER23 = 12'hB17,
    CSR_MHPMCOUNTER24 = 12'hB18,
    CSR_MHPMCOUNTER25 = 12'hB19,
    CSR_MHPMCOUNTER26 = 12'hB1A,
    CSR_MHPMCOUNTER27 = 12'hB1B,
    CSR_MHPMCOUNTER28 = 12'hB1C,
    CSR_MHPMCOUNTER29 = 12'hB1D,
    CSR_MHPMCOUNTER30 = 12'hB1E,
    CSR_MHPMCOUNTER31 = 12'hB1F,

    // Machine Counters/Timers (high)
    CSR_MCYCLEH    = 12'hB80,
    CSR_MINSTRETH  = 12'hB82,
    CSR_MHPMCOUNTER3H  = 12'hB83,
    CSR_MHPMCOUNTER4H  = 12'hB84,
    CSR_MHPMCOUNTER5H  = 12'hB85,
    CSR_MHPMCOUNTER6H  = 12'hB86,
    CSR_MHPMCOUNTER7H  = 12'hB87,
    CSR_MHPMCOUNTER8H  = 12'hB88,
    CSR_MHPMCOUNTER9H  = 12'hB89,
    CSR_MHPMCOUNTER10H = 12'hB8A,
    CSR_MHPMCOUNTER11H = 12'hB8B,
    CSR_MHPMCOUNTER12H = 12'hB8C,
    CSR_MHPMCOUNTER13H = 12'hB8D,
    CSR_MHPMCOUNTER14H = 12'hB8E,
    CSR_MHPMCOUNTER15H = 12'hB8F,
    CSR_MHPMCOUNTER16H = 12'hB90,
    CSR_MHPMCOUNTER17H = 12'hB91,
    CSR_MHPMCOUNTER18H = 12'hB92,
    CSR_MHPMCOUNTER19H = 12'hB93,
    CSR_MHPMCOUNTER20H = 12'hB94,
    CSR_MHPMCOUNTER21H = 12'hB95,
    CSR_MHPMCOUNTER22H = 12'hB96,
    CSR_MHPMCOUNTER23H = 12'hB97,
    CSR_MHPMCOUNTER24H = 12'hB98,
    CSR_MHPMCOUNTER25H = 12'hB99,
    CSR_MHPMCOUNTER26H = 12'hB9A,
    CSR_MHPMCOUNTER27H = 12'hB9B,
    CSR_MHPMCOUNTER28H = 12'hB9C,
    CSR_MHPMCOUNTER29H = 12'hB9D,
    CSR_MHPMCOUNTER30H = 12'hB9E,
    CSR_MHPMCOUNTER31H = 12'hB1F,

    // Debug CSRs
    CSR_DCSR       = 12'h7B0,
    CSR_DPC        = 12'h7B1,
    CSR_DSCRATCH0  = 12'h7B2,
    CSR_DSCRATCH1  = 12'h7B3
  } csr_num_e;

  // --------------------------
  // ALU operations
  // --------------------------
  typedef enum logic [5:0] {
    ALU_ADD,
    ALU_SUB,
    ALU_XOR,
    ALU_OR,
    ALU_AND,
    ALU_SLL,
    ALU_SRL,
    ALU_SRA,
    ALU_EQ,
    ALU_NE,
    ALU_LT,
    ALU_GE,
    ALU_LTU,
    ALU_GEU,
    ALU_SLT,
    ALU_SLTU,
    ALU_B_ADD,
    ALU_B_SUB,
    ALU_B_XOR,
    ALU_B_OR,
    ALU_B_AND,
    ALU_B_ROL,
    ALU_B_ROR,
    ALU_B_XNOR,
    ALU_B_ORCB,
    ALU_B_REV8,
    ALU_B_PACK,
    ALU_B_PACKH,
    ALU_B_PACKU,
    ALU_B_CLZ,
    ALU_B_CTZ,
    ALU_B_CPOP,
    ALU_B_SEXTB,
    ALU_B_SEXTH,
    ALU_B_ZEXTH,
    ALU_B_MIN,
    ALU_B_MAX,
    ALU_B_MINU,
    ALU_B_MAXU,
    ALU_B_SH1ADD,
    ALU_B_SH2ADD,
    ALU_B_SH3ADD,
    ALU_B_CLMUL,
    ALU_B_CLMULR,
    ALU_B_CLMULH,
    ALU_B_ANDN,
    ALU_B_ORN,
    ALU_B_XNOR3
  } alu_op_e;

  // --------------------------
  // ALU source A select
  // --------------------------
  typedef enum logic [2:0] {
    OP_A_REG_A  = 3'b000,
    OP_A_REG_B  = 3'b001,
    OP_A_REG_C  = 3'b010,
    OP_A_IMM    = 3'b011,
    OP_A_FWD    = 3'b100,
    OP_A_CURPC  = 3'b101,
    OP_A_EX_RES = 3'b110
  } op_a_sel_e;

  // --------------------------
  // ALU source B select
  // --------------------------
  typedef enum logic [1:0] {
    OP_B_REG_B  = 2'b00,
    OP_B_IMM    = 2'b01,
    OP_B_FWD    = 2'b10,
    OP_B_REG_C  = 2'b11
  } op_b_sel_e;

  // --------------------------
  // Data flow source select
  // --------------------------
  typedef enum logic [2:0] {
    WB_EX_RESULT  = 3'b000,
    WB_CSR        = 3'b001,
    WB_LSU_DATA   = 3'b010,
    WB_INVALID    = 3'b011,
    WB_CHERI      = 3'b100
  } wb_instr_source_e;

  // --------------------------
  // Mult/div operations
  // --------------------------
  typedef enum logic [1:0] {
    MD_OP_MULL  = 2'b00,
    MD_OP_MULH  = 2'b01,
    MD_OP_DIV   = 2'b10,
    MD_OP_REM   = 2'b11
  } md_op_e;

  // --------------------------
  // Instruction opcodes
  // --------------------------
  typedef enum logic [6:0] {
    OPCODE_LOAD      = 7'b00_000_11,
    OPCODE_LOAD_FP   = 7'b00_001_11,
    OPCODE_CUSTOM_0  = 7'b00_010_11,
    OPCODE_MISC_MEM  = 7'b00_011_11,
    OPCODE_OP_IMM    = 7'b00_100_11,
    OPCODE_AUIPC     = 7'b00_101_11,
    OPCODE_OP_IMM_32 = 7'b00_110_11,
    OPCODE_STORE     = 7'b01_000_11,
    OPCODE_STORE_FP  = 7'b01_001_11,
    OPCODE_CUSTOM_1  = 7'b01_010_11,
    OPCODE_AMO       = 7'b01_011_11,
    OPCODE_OP        = 7'b01_100_11,
    OPCODE_LUI       = 7'b01_101_11,
    OPCODE_OP_32     = 7'b01_110_11,
    OPCODE_MADD      = 7'b10_000_11,
    OPCODE_MSUB      = 7'b10_001_11,
    OPCODE_NMSUB     = 7'b10_010_11,
    OPCODE_NMADD     = 7'b10_011_11,
    OPCODE_FP        = 7'b10_100_11,
    OPCODE_BRANCH    = 7'b11_000_11,
    OPCODE_JALR      = 7'b11_001_11,
    OPCODE_JAL       = 7'b11_011_11,
    OPCODE_SYSTEM    = 7'b11_100_11
  } opcode_e;

  // --------------------------
  // Instruction decode
  // --------------------------
  typedef struct packed {
    logic        illegal_insn;
    logic        ecall_insn;
    logic        mret_insn;
    logic        wfi_insn;
    logic        ebreak_insn;
    logic        dret_insn;
    logic        branch_instr;
    logic        jump_instr;
    logic        jump_set;
    logic        jalr_instr;
    logic        csr_access;
    logic        csr_illegal;
    logic        sys_en;
    logic        sys_m_irq_en;
    logic        rf_we;
    logic        rf_ren_a;
    logic        rf_ren_b;
    logic        rf_ren_c;
    logic        rf_rd_a; // Use rd as source a
    logic        rf_rd_b; // Use rd as source b
    logic        rf_rd_c; // Use rd as source c
    logic        alu_en;
    logic        alu_b_sel;     // Selects B operand for branch ALU
    logic        alu_b_en;      // Enable branch ALU
    logic        alu_op_a_mux_sel;
    logic        alu_op_b_mux_sel;
    logic        mult_en;
    logic        div_en;
    logic        multdiv_sel;
    logic        mult_signed_mode;
    logic [1:0]  multdiv_operator;
    logic [1:0]  data_req;
    logic        data_we;
    logic        data_type;
    logic        data_sign_ext;
    logic        rf_we_dec;
    logic        rf_we_wb;
    logic        use_pc;
    logic        use_imm;
    logic        use_zimm;
    logic        use_csr;
    logic        lsu_req;
    logic        lsu_we;
    logic [1:0]  lsu_type;
    logic        lsu_sign_ext;
    logic        pipe_flush;
    logic        dummy_instr_en;
    logic        dummy_instr_mask;
    logic        dummy_instr_seed_en;
    logic        dummy_instr_fetch_valid;
    logic [31:0] dummy_instr_data;
  } instr_t;

  // --------------------------
  // CSR data type
  // --------------------------
  typedef struct packed {
    logic [31:0] rdata;
    logic        illegal_csr;
  } csr_resp_t;

  // --------------------------
  // LSU response type
  // --------------------------
  typedef struct packed {
    logic        valid;
    logic [31:0] rdata;
    logic        err;
  } lsu_resp_t;

  // --------------------------
  // LSU request type
  // --------------------------
  typedef struct packed {
    logic        req;
    logic        we;
    logic [31:0] addr;
    logic [31:0] wdata;
    logic [ 3:0] be;
    logic [ 1:0] data_type;
    logic        sign_ext;
  } lsu_req_t;

