module ibex_counter #(
  parameter int unsigned CounterWidth = 32
) (
  input  logic                  clk_i,
  input  logic                  rst_ni,
  input  logic                  counter_inc_i,
  input  logic                  counter_we_i,
  input  logic [CounterWidth-1:0] counter_wdata_i,
  output logic [CounterWidth-1:0] counter_val_o
);

  logic [CounterWidth-1:0] counter_d, counter_q;

  assign counter_d = counter_inc_i ? (counter_q + {{CounterWidth-1{1'b0}}, 1'b1}) :
                      counter_we_i ? counter_wdata_i :
                      counter_q;

  always_ff @(posedge clk_i or negedge rst_ni) begin
    if (!rst_ni) begin
      counter_q <= '0;
    end else begin
      counter_q <= counter_d;
    end
  end

  assign counter_val_o = counter_q;

endmodule

