// SPDX-License-Identifier: Apache-2.0

module ibex_csr #(
  parameter int unsigned      Width      = 32,
  parameter logic [Width-1:0] ResetValue = '0
) (
  input  logic                  clk_i,
  input  logic                  rst_ni,
  input  logic                  wr_en_i,
  input  logic                  rd_en_i,
  input  logic [Width-1:0]      wr_data_i,
  output logic [Width-1:0]      rd_data_o,
  // Optional: direct write (for counter updates, etc)
  input  logic                  direct_wr_en_i,
  input  logic [Width-1:0]      direct_wr_data_i
);

  logic [Width-1:0] csr_q, csr_d;

  always_comb begin
    csr_d = csr_q;
    if (direct_wr_en_i) begin
      csr_d = direct_wr_data_i;
    end else if (wr_en_i) begin
      csr_d = wr_data_i;
    end
  end

  always_ff @(posedge clk_i or negedge rst_ni) begin
    if (!rst_ni) begin
      csr_q <= ResetValue;
    end else begin
      csr_q <= csr_d;
    end
  end

  assign rd_data_o = csr_q;

endmodule

