  input  logic                  csr_access_i,
  input  ibex_pkg::csr_num_e    csr_addr_i,
  input  logic [31:0]           csr_wdata_i,
  input  ibex_pkg::csr_op_e     csr_op_i,
  input  logic                  csr_op_en_i,
  output logic [31:0]           csr_rdata_o,
  output logic                  illegal_csr_insn_o
);

  import ibex_pkg::*;

  localparam int unsigned NUM_HPM_COUNTERS = MHPMCounterNum;
  localparam int unsigned MAX_HPM_COUNTERS = 29;

  function automatic logic [31:0] get_counter_mask_low();
    if (MHPMCounterWidth >= 64) return 32'hFFFFFFFF;
    else if (MHPMCounterWidth >= 32) return 32'hFFFFFFFF;
    else return (32'hFFFFFFFF << MHPMCounterWidth);
  endfunction

  function automatic logic [31:0] get_counter_mask_high();
    if (MHPMCounterWidth >= 64) return 32'hFFFFFFFF;
    else if (MHPMCounterWidth > 32) return (32'hFFFFFFFF << (MHPMCounterWidth - 32));
    else return 32'h00000000;
  endfunction

  localparam logic [31:0] COUNTER_MASK_LOW  = get_counter_mask_low();
  localparam logic [31:0] COUNTER_MASK_HIGH = get_counter_mask_high();

  // CSR register storage
  logic [31:0] mstatus_q, mstatus_d;
  logic [31:0] mie_q, mie_d;
  logic [31:0] mtvec_q, mtvec_d;
  logic [31:0] mscratch_q, mscratch_d;
  logic [31:0] mepc_q, mepc_d;
  logic [31:0] mcause_q, mcause_d;
  logic [31:0] mtval_q, mtval_d;
  logic [31:0] mip_q, mip_d;
  logic [31:0] mcountinhibit_q, mcountinhibit_d;
  logic [31:0] mseccfg_q, mseccfg_d;
  logic [31:0] cpuctrl_q, cpuctrl_d;
  logic [31:0] dcsr_q, dcsr_d;
  logic [31:0] dpc_q, dpc_d;
  logic [31:0] dscratch0_q, dscratch0_d;
  logic [31:0] dscratch1_q, dscratch1_d;

  logic [31:0] mhpm_event     [32];
  logic [31:0] mhpm_event_d   [32];

  logic [31:0] pmpcfg  [16];
  logic [31:0] pmpcfg_d[16];
  logic [31:0] pmpaddr  [16];
  logic [31:0] pmpaddr_d[16];

  logic [63:0] mcycle_counter, mcycle_counter_d;
  logic [63:0] minstret_counter, minstret_counter_d;
  logic [63:0] mhpm_counter   [MAX_HPM_COUNTERS];
  logic [63:0] mhpm_counter_d [MAX_HPM_COUNTERS];

  // Write enable signals
  logic        csr_wr;
  logic        csr_rd;

  // Computed mcountinhibit mask
  logic [31:0] mcountinhibit_mask;

  // Read data from matching register
  logic [31:0] csr_rdata;

  // Illegal CSR check
  logic        illegal_csr;

  assign csr_wr = csr_access_i & csr_op_en_i & (csr_op_i != CSR_OP_READ);
  assign csr_rd = csr_access_i;

  // mcountinhibit mask: only implemented counters can be inhibited
  assign mcountinhibit_mask = 32'hFFFFFFF8 |
      (~(NUM_HPM_COUNTERS > 0 ? ((32'h1 << NUM_HPM_COUNTERS) - 1) : 32'h0) << 3);

  // ==========================================================================
  // CSR Read Data Mux
  // ==========================================================================
  always_comb begin
    csr_rdata = 32'h0;
    illegal_csr = 1'b0;

    unique case (csr_addr_i)
      CSR_MVENDORID:  csr_rdata = 32'h0000_0000;
      CSR_MARCHID:    csr_rdata = 32'h0000_0000;
      CSR_MIMPID:     csr_rdata = 32'h0000_0000;
      CSR_MHARTID:    csr_rdata = 32'h0000_0000;
      CSR_MSTATUS:    csr_rdata = mstatus_q;
      CSR_MISA:       csr_rdata = MISA_VALUE;
      CSR_MIE:        csr_rdata = mie_q;
      CSR_MTVEC:      csr_rdata = mtvec_q;
      CSR_MSCRATCH:   csr_rdata = mscratch_q;
      CSR_MEPC:       csr_rdata = mepc_q;
      CSR_MCAUSE:     csr_rdata = mcause_q;
      CSR_MTVAL:      csr_rdata = mtval_q;
      CSR_MIP:        csr_rdata = mip_q;
      CSR_MCOUNTINHIBIT: csr_rdata = mcountinhibit_q;

      CSR_CPUCTRL:    csr_rdata = cpuctrl_q;
      CSR_MSECCFG:    csr_rdata = mseccfg_q;
      CSR_MSECCFGH:   csr_rdata = 32'h0;

      CSR_DCSR:       csr_rdata = DbgTriggerEn ? dcsr_q : 32'h0;
      CSR_DPC:        csr_rdata = DbgTriggerEn ? dpc_q : 32'h0;
      CSR_DSCRATCH0:  csr_rdata = DbgTriggerEn ? dscratch0_q : 32'h0;
      CSR_DSCRATCH1:  csr_rdata = DbgTriggerEn ? dscratch1_q : 32'h0;

      CSR_MCYCLE:     csr_rdata = mcycle_counter[31:0];
      CSR_MINSTRET:   csr_rdata = minstret_counter[31:0];
      CSR_MCYCLEH:    csr_rdata = mcycle_counter[63:32];
      CSR_MINSTRETH:  csr_rdata = minstret_counter[63:32];

      CSR_MHPMEVENT3, CSR_MHPMEVENT4, CSR_MHPMEVENT5,
      CSR_MHPMEVENT6, CSR_MHPMEVENT7, CSR_MHPMEVENT8,
      CSR_MHPMEVENT9, CSR_MHPMEVENT10, CSR_MHPMEVENT11,
      CSR_MHPMEVENT12, CSR_MHPMEVENT13, CSR_MHPMEVENT14,
      CSR_MHPMEVENT15, CSR_MHPMEVENT16, CSR_MHPMEVENT17,
      CSR_MHPMEVENT18, CSR_MHPMEVENT19, CSR_MHPMEVENT20,
      CSR_MHPMEVENT21, CSR_MHPMEVENT22, CSR_MHPMEVENT23,
      CSR_MHPMEVENT24, CSR_MHPMEVENT25, CSR_MHPMEVENT26,
      CSR_MHPMEVENT27, CSR_MHPMEVENT28, CSR_MHPMEVENT29,
      CSR_MHPMEVENT30, CSR_MHPMEVENT31: begin
        int idx = int'(csr_addr_i) - int'(CSR_MHPMEVENT3);
        if (idx >= 0 && idx < MAX_HPM_COUNTERS && idx < NUM_HPM_COUNTERS)
          csr_rdata = mhpm_event[idx];
        else
          csr_rdata = 32'h0;
      end

      CSR_MHPMCOUNTER3, CSR_MHPMCOUNTER4, CSR_MHPMCOUNTER5,
      CSR_MHPMCOUNTER6, CSR_MHPMCOUNTER7, CSR_MHPMCOUNTER8,
      CSR_MHPMCOUNTER9, CSR_MHPMCOUNTER10, CSR_MHPMCOUNTER11,
      CSR_MHPMCOUNTER12, CSR_MHPMCOUNTER13, CSR_MHPMCOUNTER14,
      CSR_MHPMCOUNTER15, CSR_MHPMCOUNTER16, CSR_MHPMCOUNTER17,
      CSR_MHPMCOUNTER18, CSR_MHPMCOUNTER19, CSR_MHPMCOUNTER20,
      CSR_MHPMCOUNTER21, CSR_MHPMCOUNTER22, CSR_MHPMCOUNTER23,
      CSR_MHPMCOUNTER24, CSR_MHPMCOUNTER25, CSR_MHPMCOUNTER26,
      CSR_MHPMCOUNTER27, CSR_MHPMCOUNTER28, CSR_MHPMCOUNTER29,
      CSR_MHPMCOUNTER30, CSR_MHPMCOUNTER31: begin
        int idx = int'(csr_addr_i) - int'(CSR_MHPMCOUNTER3);
        if (idx >= 0 && idx < MAX_HPM_COUNTERS && idx < NUM_HPM_COUNTERS)
          csr_rdata = mhpm_counter[idx][31:0];
        else
          csr_rdata = 32'h0;
      end

      CSR_MHPMCOUNTER3H, CSR_MHPMCOUNTER4H, CSR_MHPMCOUNTER5H,
      CSR_MHPMCOUNTER6H, CSR_MHPMCOUNTER7H, CSR_MHPMCOUNTER8H,
      CSR_MHPMCOUNTER9H, CSR_MHPMCOUNTER10H, CSR_MHPMCOUNTER11H,
      CSR_MHPMCOUNTER12H, CSR_MHPMCOUNTER13H, CSR_MHPMCOUNTER14H,
      CSR_MHPMCOUNTER15H, CSR_MHPMCOUNTER16H, CSR_MHPMCOUNTER17H,
      CSR_MHPMCOUNTER18H, CSR_MHPMCOUNTER19H, CSR_MHPMCOUNTER20H,
      CSR_MHPMCOUNTER21H, CSR_MHPMCOUNTER22H, CSR_MHPMCOUNTER23H,
      CSR_MHPMCOUNTER24H, CSR_MHPMCOUNTER25H, CSR_MHPMCOUNTER26H,
      CSR_MHPMCOUNTER27H, CSR_MHPMCOUNTER28H, CSR_MHPMCOUNTER29H,
      CSR_MHPMCOUNTER30H, CSR_MHPMCOUNTER31H: begin
        int idx = int'(csr_addr_i) - int'(CSR_MHPMCOUNTER3H);
        if (idx >= 0 && idx < MAX_HPM_COUNTERS && idx < NUM_HPM_COUNTERS)
          csr_rdata = mhpm_counter[idx][63:32];
        else
          csr_rdata = 32'h0;
      end

      CSR_PMPCFG0, CSR_PMPCFG1, CSR_PMPCFG2, CSR_PMPCFG3: begin
        int idx = int'(csr_addr_i) - int'(CSR_PMPCFG0);
        if (PMPEnable && (idx < int'(PMPNumRegions + 3) / 4))
          csr_rdata = pmpcfg[idx];
        else
          csr_rdata = 32'h0;
      end

      CSR_PMPADDR0, CSR_PMPADDR1, CSR_PMPADDR2, CSR_PMPADDR3,
      CSR_PMPADDR4, CSR_PMPADDR5, CSR_PMPADDR6, CSR_PMPADDR7,
      CSR_PMPADDR8, CSR_PMPADDR9, CSR_PMPADDR10, CSR_PMPADDR11,
      CSR_PMPADDR12, CSR_PMPADDR13, CSR_PMPADDR14, CSR_PMPADDR15: begin
        int idx = int'(csr_addr_i) - int'(CSR_PMPADDR0);
        if (PMPEnable && (idx < int'(PMPNumRegions)))
          csr_rdata = pmpaddr[idx];
        else
          csr_rdata = 32'h0;
      end

      default: begin
        csr_rdata = 32'h0;
        illegal_csr = 1'b1;
      end
    endcase
  end

  assign csr_rdata_o = csr_rdata;
  assign illegal_csr_insn_o = illegal_csr & csr_access_i;

  // ==========================================================================
  // Register Update Logic (combinational next-state)
  // ==========================================================================

  // Default: hold values
  always_comb begin
    mstatus_d = mstatus_q;
    mie_d = mie_q;
    mtvec_d = mtvec_q;
    mscratch_d = mscratch_q;
    mepc_d = mepc_q;
    mcause_d = mcause_q;
    mtval_d = mtval_q;
    mip_d = mip_q;
    mcountinhibit_d = mcountinhibit_q;
    mseccfg_d = mseccfg_q;
    cpuctrl_d = cpuctrl_q;
    dcsr_d = dcsr_q;
    dpc_d = dpc_q;
    dscratch0_d = dscratch0_q;
    dscratch1_d = dscratch1_q;

    mcycle_counter_d = mcycle_counter + 64'd1;
    minstret_counter_d = minstret_counter;
    for (int i = 0; i < MAX_HPM_COUNTERS; i++) begin
      mhpm_counter_d[i] = mhpm_counter[i];
      mhpm_event_d[i] = mhpm_event[i];
    end
    for (int i = 0; i < 16; i++) begin
      pmpcfg_d[i] = pmpcfg[i];
      pmpaddr_d[i] = pmpaddr[i];
    end
  end

  // Write logic
  if (1) begin : gen_csr_write
    always_comb begin
      if (csr_wr) begin
        unique case (csr_addr_i)
          CSR_MSTATUS:   mstatus_d = apply_csr_op(mstatus_q, csr_wdata_i, csr_op_i, 32'h0000_1888);
          CSR_MIE:       mie_d = apply_csr_op(mie_q, csr_wdata_i, csr_op_i, 32'h0000_0888);
          CSR_MTVEC:     mtvec_d = apply_csr_op(mtvec_q, csr_wdata_i, csr_op_i, 32'hFFFFFFFE);
          CSR_MSCRATCH:  mscratch_d = apply_csr_op(mscratch_q, csr_wdata_i, csr_op_i, 32'h00000000);
          CSR_MEPC:      mepc_d = apply_csr_op(mepc_q, csr_wdata_i, csr_op_i, 32'h00000000);
          CSR_MCAUSE:    mcause_d = apply_csr_op(mcause_q, csr_wdata_i, csr_op_i, 32'h80000000);
          CSR_MTVAL:     mtval_d = apply_csr_op(mtval_q, csr_wdata_i, csr_op_i, 32'h00000000);
          CSR_MIP:       mip_d = mip_q; // Read-only for software
          CSR_MCOUNTINHIBIT: mcountinhibit_d = apply_csr_op_lock(mcountinhibit_q, csr_wdata_i, csr_op_i, mcountinhibit_mask);
          CSR_CPUCTRL:   cpuctrl_d = apply_csr_op(cpuctrl_q, csr_wdata_i, csr_op_i, 32'h00000007);
          CSR_MSECCFG:   mseccfg_d = apply_csr_op_mseccfg(mseccfg_q, csr_wdata_i, csr_op_i);
          CSR_MSECCFGH:  ; // Ignore writes

          CSR_DCSR:      if (DbgTriggerEn) dcsr_d = apply_csr_op(dcsr_q, csr_wdata_i, csr_op_i, 32'h00000000);
          CSR_DPC:       if (DbgTriggerEn) dpc_d = apply_csr_op(dpc_q, csr_wdata_i, csr_op_i, 32'h00000000);
          CSR_DSCRATCH0: if (DbgTriggerEn) dscratch0_d = apply_csr_op(dscratch0_q, csr_wdata_i, csr_op_i, 32'h00000000);
          CSR_DSCRATCH1: if (DbgTriggerEn) dscratch1_d = apply_csr_op(dscratch1_q, csr_wdata_i, csr_op_i, 32'h00000000);

          CSR_MCYCLE:     mcycle_counter_d[31:0] = apply_csr_op(mcycle_counter[31:0], csr_wdata_i, csr_op_i, 32'hFFFFFFFF);
          CSR_MINSTRET:   minstret_counter_d[31:0] = apply_csr_op(minstret_counter[31:0], csr_wdata_i, csr_op_i, 32'hFFFFFFFF);
          CSR_MCYCLEH:    mcycle_counter_d[63:32] = apply_csr_op(mcycle_counter[63:32], csr_wdata_i, csr_op_i, 32'hFFFFFFFF);
          CSR_MINSTRETH:  minstret_counter_d[63:32] = apply_csr_op(minstret_counter[63:32], csr_wdata_i, csr_op_i, 32'hFFFFFFFF);

          CSR_MHPMEVENT3, CSR_MHPMEVENT4, CSR_MHPMEVENT5,
          CSR_MHPMEVENT6, CSR_MHPMEVENT7, CSR_MHPMEVENT8,
          CSR_MHPMEVENT9, CSR_MHPMEVENT10, CSR_MHPMEVENT11,
          CSR_MHPMEVENT12, CSR_MHPMEVENT13, CSR_MHPMEVENT14,
          CSR_MHPMEVENT15, CSR_MHPMEVENT16, CSR_MHPMEVENT17,
          CSR_MHPMEVENT18, CSR_MHPMEVENT19, CSR_MHPMEVENT20,
          CSR_MHPMEVENT21, CSR_MHPMEVENT22, CSR_MHPMEVENT23,
          CSR_MHPMEVENT24, CSR_MHPMEVENT25, CSR_MHPMEVENT26,
          CSR_MHPMEVENT27, CSR_MHPMEVENT28, CSR_MHPMEVENT29,
          CSR_MHPMEVENT30, CSR_MHPMEVENT31: begin
            int idx = int'(csr_addr_i) - int'(CSR_MHPMEVENT3);
            if (idx >= 0 && idx < MAX_HPM_COUNTERS && idx < NUM_HPM_COUNTERS)
              mhpm_event_d[idx] = apply_csr_op_lock(mhpm_event[idx], csr_wdata_i, csr_op_i, 32'h00000000);
          end

          CSR_MHPMCOUNTER3, CSR_MHPMCOUNTER4, CSR_MHPMCOUNTER5,
          CSR_MHPMCOUNTER6, CSR_MHPMCOUNTER7, CSR_MHPMCOUNTER8,
          CSR_MHPMCOUNTER9, CSR_MHPMCOUNTER10, CSR_MHPMCOUNTER11,
          CSR_MHPMCOUNTER12, CSR_MHPMCOUNTER13, CSR_MHPMCOUNTER14,
          CSR_MHPMCOUNTER15, CSR_MHPMCOUNTER16, CSR_MHPMCOUNTER17,
          CSR_MHPMCOUNTER18, CSR_MHPMCOUNTER19, CSR_MHPMCOUNTER20,
          CSR_MHPMCOUNTER21, CSR_MHPMCOUNTER22, CSR_MHPMCOUNTER23,
          CSR_MHPMCOUNTER24, CSR_MHPMCOUNTER25, CSR_MHPMCOUNTER26,
          CSR_MHPMCOUNTER27, CSR_MHPMCOUNTER28, CSR_MHPMCOUNTER29,
          CSR_MHPMCOUNTER30, CSR_MHPMCOUNTER31: begin
            int idx = int'(csr_addr_i) - int'(CSR_MHPMCOUNTER3);
            if (idx >= 0 && idx < MAX_HPM_COUNTERS && idx < NUM_HPM_COUNTERS)
              mhpm_counter_d[idx][31:0] = apply_csr_op_lock(mhpm_counter[idx][31:0], csr_wdata_i, csr_op_i, COUNTER_MASK_LOW);
          end

          CSR_MHPMCOUNTER3H, CSR_MHPMCOUNTER4H, CSR_MHPMCOUNTER5H,
          CSR_MHPMCOUNTER6H, CSR_MHPMCOUNTER7H, CSR_MHPMCOUNTER8H,
          CSR_MHPMCOUNTER9H, CSR_MHPMCOUNTER10H, CSR_MHPMCOUNTER11H,
          CSR_MHPMCOUNTER12H, CSR_MHPMCOUNTER13H, CSR_MHPMCOUNTER14H,
          CSR_MHPMCOUNTER15H, CSR_MHPMCOUNTER16H, CSR_MHPMCOUNTER17H,
          CSR_MHPMCOUNTER18H, CSR_MHPMCOUNTER19H, CSR_MHPMCOUNTER20H,
          CSR_MHPMCOUNTER21H, CSR_MHPMCOUNTER22H, CSR_MHPMCOUNTER23H,
          CSR_MHPMCOUNTER24H, CSR_MHPMCOUNTER25H, CSR_MHPMCOUNTER26H,
          CSR_MHPMCOUNTER27H, CSR_MHPMCOUNTER28H, CSR_MHPMCOUNTER29H,
          CSR_MHPMCOUNTER30H, CSR_MHPMCOUNTER31H: begin
            int idx = int'(csr_addr_i) - int'(CSR_MHPMCOUNTER3H);
            if (idx >= 0 && idx < MAX_HPM_COUNTERS && idx < NUM_HPM_COUNTERS)
              mhpm_counter_d[idx][63:32] = apply_csr_op_lock(mhpm_counter[idx][63:32], csr_wdata_i, csr_op_i, COUNTER_MASK_HIGH);
          end

          CSR_PMPCFG0, CSR_PMPCFG1, CSR_PMPCFG2, CSR_PMPCFG3: begin
            int idx = int'(csr_addr_i) - int'(CSR_PMPCFG0);
            if (PMPEnable && (idx < int'(PMPNumRegions + 3) / 4))
              pmpcfg_d[idx] = apply_csr_op_pmpcfg(pmpcfg[idx], csr_wdata_i, csr_op_i, idx);
          end

          CSR_PMPADDR0, CSR_PMPADDR1, CSR_PMPADDR2, CSR_PMPADDR3,
          CSR_PMPADDR4, CSR_PMPADDR5, CSR_PMPADDR6, CSR_PMPADDR7,
          CSR_PMPADDR8, CSR_PMPADDR9, CSR_PMPADDR10, CSR_PMPADDR11,
          CSR_PMPADDR12, CSR_PMPADDR13, CSR_PMPADDR14, CSR_PMPADDR15: begin
            int idx = int'(csr_addr_i) - int'(CSR_PMPADDR0);
            if (PMPEnable && (idx < int'(PMPNumRegions)))
              pmpaddr_d[idx] = apply_csr_op_pmpaddr(pmpaddr[idx], csr_wdata_i, csr_op_i, idx);
          end

          default: ;
        endcase
      end
    end
  end

  // Mcycle always increments (unless inhibited)
  always_comb begin
    if (!mcountinhibit_q[0] && !csr_wr_match(CSR_MCYCLE) && !csr_wr_match(CSR_MCYCLEH))
      mcycle_counter_d = mcycle_counter + 64'd1;
  end

  // ==========================================================================
  // Sequential update
  // ==========================================================================
  always_ff @(posedge clk_i or negedge rst_ni) begin
    if (!rst_ni) begin
      mstatus_q       <= 32'h0000_1800;
      mie_q           <= 32'h0;
      mtvec_q         <= 32'h0;
      mscratch_q      <= 32'h0;
      mepc_q          <= 32'h0;
      mcause_q        <= 32'h0;
      mtval_q         <= 32'h0;
      mip_q           <= 32'h0;
      mcountinhibit_q <= 32'h0000_0000;
      mseccfg_q       <= 32'h0;
      cpuctrl_q       <= 32'h0;
      dcsr_q          <= 32'h0;
      dpc_q           <= 32'h0;
      dscratch0_q     <= 32'h0;
      dscratch1_q     <= 32'h0;

      mcycle_counter   <= 64'h0;
      minstret_counter <= 64'h0;
      for (int i = 0; i < MAX_HPM_COUNTERS; i++) begin
        mhpm_counter[i] <= 64'h0;
        mhpm_event[i]   <= (32'h1 << i);
      end
      for (int i = 0; i < 16; i++) begin
        pmpcfg[i]  <= 32'h0;
        pmpaddr[i] <= 32'h0;
      end
    end else begin
      mstatus_q       <= mstatus_d;
      mie_q           <= mie_d;
      mtvec_q         <= mtvec_d;
      mscratch_q      <= mscratch_d;
      mepc_q          <= mepc_d;
      mcause_q        <= mcause_d;
      mtval_q         <= mtval_d;
      mip_q           <= mip_d;
      mcountinhibit_q <= mcountinhibit_d;
      mseccfg_q       <= mseccfg_d;
      cpuctrl_q       <= cpuctrl_d;
      dcsr_q          <= dcsr_d;
      dpc_q           <= dpc_d;
      dscratch0_q     <= dscratch0_d;
      dscratch1_q     <= dscratch1_d;

      mcycle_counter   <= mcycle_counter_d;
      minstret_counter <= minstret_counter_d;
      for (int i = 0; i < MAX_HPM_COUNTERS; i++) begin
        mhpm_counter[i] <= mhpm_counter_d[i];
        mhpm_event[i]   <= mhpm_event_d[i];
      end
      for (int i = 0; i < 16; i++) begin
        pmpcfg[i]  <= pmpcfg_d[i];
        pmpaddr[i] <= pmpaddr_d[i];
      end
    end
  end

  // ==========================================================================
  // Helper functions
  // ==========================================================================

  function automatic logic csr_wr_match(input csr_num_e addr);
    return csr_wr && (csr_addr_i == addr);
  endfunction

  function automatic logic [31:0] apply_csr_op(
      input logic [31:0] cur_val, wdata, input csr_op_e op, input logic [31:0] lock_mask);
    unique case (op)
      CSR_OP_WRITE: return (cur_val & lock_mask) | (wdata & ~lock_mask);
      CSR_OP_SET:   return cur_val | (wdata & ~lock_mask);
      CSR_OP_CLEAR: return cur_val & (~wdata | lock_mask);
      default:      return cur_val;
    endcase
  endfunction

  function automatic logic [31:0] apply_csr_op_lock(
      input logic [31:0] cur_val, wdata, input csr_op_e op, input logic [31:0] lock_mask);
    unique case (op)
      CSR_OP_WRITE: return wdata & ~lock_mask;
      CSR_OP_SET:   return cur_val | (wdata & ~lock_mask);
      CSR_OP_CLEAR: return cur_val & (~wdata | lock_mask);
      default:      return cur_val;
    endcase
  endfunction

  function automatic logic [31:0] apply_csr_op_mseccfg(
      input logic [31:0] cur_val, wdata, input csr_op_e op);
    logic [31:0] lock_mask;
    lock_mask = 32'hFFFFFFF8;

    // RLB lock: if RLB == 0 and any PMPCFG has L bit set
    if (!cur_val[2] && mseccfg_pmp_locked())
      lock_mask[2] = 1'b1;

    // MMWP lock: once set, cannot be unset
    if (cur_val[1])
      lock_mask[1] = 1'b1;

    // MML lock: once set, cannot be unset
    if (cur_val[0])
      lock_mask[0] = 1'b1;

    return apply_csr_op(cur_val, wdata, op, lock_mask);
  endfunction

  function automatic logic mseccfg_pmp_locked();
    for (int i = 0; i < 16; i = i + 4) begin
      if (PMPEnable && (i/4 < (PMPNumRegions + 3) / 4)) begin
        if (pmpcfg[i/4] != 32'h0)
          if ((pmpcfg[i/4] & 32'h80808080) != 32'h0)
            return 1'b1;
      end
    end
    return 1'b0;
  endfunction

  function automatic logic [31:0] apply_csr_op_pmpcfg(
      input logic [31:0] cur_val, wdata, input csr_op_e op, input int cfg_idx);
    logic [31:0] lock_mask;
    logic [31:0] raw_result;

    // Lock mask: each byte is locked if its L bit is set
    lock_mask = 32'h0;
    if (cur_val[7])   lock_mask[7:0]   = 8'hFF;
    if (cur_val[15])  lock_mask[15:8]  = 8'hFF;
    if (cur_val[23])  lock_mask[23:16] = 8'hFF;
    if (cur_val[31])  lock_mask[31:24] = 8'hFF;

    // If MSECCFG.RLB is set, everything is unlocked
    if (mseccfg_q[2])
      lock_mask = 32'h0;

    raw_result = apply_csr_op(cur_val, wdata, op, lock_mask);

    // Apply RAZ mask: bits 7(L), 6:5(reserved), 4(X), 3(W), 2:1(reserved), 0(R)
    // RAZ mask = 0x9F9F9F9F means only bits 0,3,4,7 are R/W
    // Actually: 0x9F = 1001_1111 → bits 7,4,3,0 only
    //   bit 7 = L (lock)
    //   bit 6 = reserved → 0
    //   bit 5 = reserved → 0
    //   bit 4 = X
    //   bit 3 = W
    //   bit 2 = reserved → 0
    //   bit 1 = reserved → 0
    //   bit 0 = R
    // Wait, the model says raz_mask_ = 0x9F9F9F9F
    // 0x9F = 1001_1111 → bits 7(L),4(X),3(W),0(R) are kept, bits 6,5,2,1 RAZ
    // But the model writes: cfg_val &= raz_mask_
    // Then: HandleReservedVals: if not MML, check for W=1,R=0 (invalid)
    return handle_pmpcfg_reserved(raw_result);
  endfunction

  function automatic logic [31:0] handle_pmpcfg_reserved(input logic [31:0] cfg_val);
    logic [31:0] result;
    result = cfg_val & 32'h9F9F9F9F;

    if (mseccfg_q[0]) // MML set - no reserved L/R/W/X values
      return result;

    for (int i = 0; i < 4; i++) begin
      if (((result >> (8 * i)) & 8'h03) == 8'h02) // W=1, R=0 → reserved
        result &= ~(32'h03 << (8 * i));
    end

    return result;
  endfunction

  function automatic logic [31:0] apply_csr_op_pmpaddr(
      input logic [31:0] cur_val, wdata, input csr_op_e op, input int addr_idx);
    logic [31:0] lock_mask;
    logic [31:0] cfg_val, cfg_plus1_val;
    int cfg_idx, cfg_plus1_idx;

    cfg_idx = addr_idx / 4;
    cfg_plus1_idx = (addr_idx + 1) / 4;

    cfg_val = pmpcfg[cfg_idx];
    cfg_plus1_val = (addr_idx < 15) ? pmpcfg[cfg_plus1_idx] : 32'h0;

    cfg_val = (cfg_val >> ((addr_idx & 3) * 8)) & 8'hFF;
    cfg_plus1_val = (cfg_plus1_val >> (((addr_idx + 1) & 3) * 8)) & 8'hFF;

    // Locked if L bit is set or next region is TOR mode
    if ((cfg_val[7]) || ((cfg_plus1_val[4:1] == 4'b0100)))
      lock_mask = 32'hFFFFFFFF;
    else
      lock_mask = 32'h0;

    return apply_csr_op(cur_val, wdata, op, lock_mask);
  endfunction

  // Assertions
  `ASSERT_KNOWN(MHPMCounterWidthCheck, MHPMCounterWidth >= 32)

endmodule

