  // Writeback instruction type
  // ====================================
  typedef enum logic [2:0] {
    WB_INSTR_LOAD    = 3'b000,
    WB_INSTR_STORE   = 3'b001,
    WB_INSTR_OTHER   = 3'b010,
    WB_INSTR_EXC     = 3'b011,
    WB_INSTR_LOAD_ERR = 3'b100,
    WB_INSTR_STORE_ERR = 3'b101
  } wb_instr_type_e;

  // ====================================
  // Crash dump type
  // ====================================
  typedef struct packed {
    logic [31:0] mtval;
    logic [31:0] mepc;
    logic [31:0] mcause;
  } crash_dump_t;

  // ====================================
  // Instruction expansion enum
  // ====================================
  typedef enum logic {
    INSTR_NOT_EXPANDED = 1'b0,
    INSTR_EXPANDED     = 1'b1
  } instr_exp_e;

  // ====================================
  // MUBI (Multi-Bit Encoding) type
  // ====================================
  typedef logic [3:0] ibex_mubi_t;

  localparam ibex_mubi_t IbexMuBiOn  = 4'b0110;
  localparam ibex_mubi_t IbexMuBiOff = 4'b1001;

  // ====================================
  // LFSR types
  // ====================================
  typedef logic [31:0] lfsr_seed_t;
  typedef logic [31:0] lfsr_perm_t;
  localparam lfsr_seed_t RndCnstLfsrSeedDefault = '0;
  localparam lfsr_perm_t RndCnstLfsrPermDefault = '0;

  // ====================================
  // ICache constants
  // ====================================
  localparam int unsigned IC_NUM_WAYS  = 2;
  localparam int unsigned IC_INDEX_W   = 8;
  localparam int unsigned BUS_SIZE     = 32;
  localparam int unsigned IC_TAG_SIZE  = 25;
  localparam int unsigned IC_LINE_SIZE = 128;

  // ====================================
  // Ibex specific constants
  // ====================================
  localparam int unsigned MHPMCounterMax = 29;

  localparam logic [1:0] PRIV_LVL_M = 2'b11;

  localparam logic [31:0] CPUCTRL_ICACHE_ENABLE  = 32'h0000_0001;
  localparam logic [31:0] CPUCTRL_DIT_ENABLE     = 32'h0000_0002;
  localparam logic [31:0] CPUCTRL_DUMMY_INSTR_EN = 32'h0000_0004;

  localparam logic [31:0] MSTATUS_MIE  = 32'h0000_0008;
  localparam logic [31:0] MSTATUS_MPIE = 32'h0000_0080;
  localparam logic [31:0] MSTATUS_MPP  = 32'h0000_1800;
  localparam logic [31:0] MSTATUS_FS   = 32'h0000_6000;

  localparam logic [31:0] MTVEC_MODE_DIRECT   = 32'h0000_0000;
  localparam logic [31:0] MTVEC_MODE_VECTORED = 32'h0000_0001;

  localparam logic [31:0] MCAUSE_IRQ_BIT = 32'h8000_0000;

  localparam logic [4:0] EXC_INSTR_ACCESS_FAULT = 5'd1;
  localparam logic [4:0] EXC_ILLEGAL_INSTR      = 5'd2;
  localparam logic [4:0] EXC_BREAKPOINT         = 5'd3;
  localparam logic [4:0] EXC_LOAD_ACCESS_FAULT  = 5'd5;
  localparam logic [4:0] EXC_STORE_ACCESS_FAULT = 5'd7;
  localparam logic [4:0] EXC_ECALL_MMODE        = 5'd11;
  localparam logic [4:0] EXC_INSTR_BUS_FAULT    = 5'd12;
  localparam logic [4:0] EXC_LOAD_BUS_FAULT     = 5'd13;
  localparam logic [4:0] EXC_STORE_BUS_FAULT    = 5'd15;

  localparam logic [4:0] IRQ_TIMER = 5'd7;

  localparam logic [31:0] MISA_VALUE = 32'h0010_0100;

endpackage

