`include "prim_assert.sv"

module ibex_cs_registers #(
  parameter bit               DbgTriggerEn      = 1'b0,
  parameter int unsigned      DbgHwBreakNum     = 1,
  parameter bit               DataIndTiming     = 1'b0,
  parameter bit               DummyInstructions = 1'b0,
  parameter bit               ShadowCSR         = 1'b0,
  parameter bit               ICache            = 1'b0,
  parameter int unsigned      MHPMCounterNum    = 8,
  parameter int unsigned      MHPMCounterWidth  = 40,
  parameter bit               PMPEnable         = 1'b0,
  parameter int unsigned      PMPGranularity    = 0,
  parameter int unsigned      PMPNumRegions     = 4,
  parameter ibex_pkg::pmp_cfg_t     PMPRstCfg   [ibex_pkg::PMP_MAX_REGIONS] = '{default:'0},
  parameter logic [ibex_pkg::PMP_ADDR_MSB:0] PMPRstAddr [ibex_pkg::PMP_MAX_REGIONS] = '{default:'0},
  parameter ibex_pkg::pmp_mseccfg_t PMPRstMseccfg = '0,
  parameter bit               RV32E             = 1'b0,
  parameter ibex_pkg::rv32m_e RV32M             = ibex_pkg::RV32MFast,
  parameter ibex_pkg::rv32b_e RV32B             = ibex_pkg::RV32BNone,
  parameter logic [31:0]      CsrMvendorId     = 32'b0,
  parameter logic [31:0]      CsrMimpId        = 32'b0
) (
  input  logic                  clk_i,
  input  logic                  rst_ni,

  input  logic [31:0]           hart_id_i,
  output ibex_pkg::ibex_mubi_t  priv_mode_id_o,
  output ibex_pkg::ibex_mubi_t  priv_mode_lsu_o,

  output logic [31:0]           csr_mtvec_o,
  input  logic                  csr_mtvec_init_i,
  input  logic [31:0]           boot_addr_i,

  input  logic                  csr_access_i,
  input  ibex_pkg::csr_num_e    csr_addr_i,
  input  logic [31:0]           csr_wdata_i,
  input  ibex_pkg::csr_op_e     csr_op_i,
  input  logic                  csr_op_en_i,
  output logic [31:0]           csr_rdata_o,

  input  logic                  irq_software_i,
  input  logic                  irq_timer_i,
  input  logic                  irq_external_i,
  input  logic [14:0]           irq_fast_i,
  input  logic                  nmi_mode_i,
  output logic                  irq_pending_o,
  output ibex_pkg::irqs_t       irqs_o,
  output logic                  csr_mstatus_mie_o,
  output logic                  csr_mstatus_tw_o,
  output logic [31:0]           csr_mepc_o,
  output logic [31:0]           csr_mtval_o,

  output ibex_pkg::pmp_cfg_t                      csr_pmp_cfg_o     [ibex_pkg::PMP_MAX_REGIONS],
  output logic [ibex_pkg::PMP_ADDR_MSB:0]         csr_pmp_addr_o    [ibex_pkg::PMP_MAX_REGIONS],
  output ibex_pkg::pmp_mseccfg_t                  csr_pmp_mseccfg_o,

  output logic [31:0]           csr_depc_o,
  input  logic                  debug_mode_i,
  input  logic                  debug_mode_entering_i,
  input  ibex_pkg::exc_cause_t  debug_cause_i,
  input  logic                  debug_csr_save_i,
  output logic                  debug_single_step_o,
  output logic                  debug_ebreakm_o,
  output logic                  debug_ebreaku_o,
  output logic                  trigger_match_o,

  input  logic [31:0]           pc_if_i,
  input  logic [31:0]           pc_id_i,
  input  logic [31:0]           pc_wb_i,

  output logic                  data_ind_timing_o,
  output logic                  dummy_instr_en_o,
  output logic [2:0]            dummy_instr_mask_o,
  output logic                  dummy_instr_seed_en_o,
  output logic [31:0]           dummy_instr_seed_o,
  output logic                  icache_enable_o,
  output logic                  csr_shadow_err_o,
  input  logic                  ic_scr_key_valid_i,

  input  logic                  csr_save_if_i,
  input  logic                  csr_save_id_i,
  input  logic                  csr_save_wb_i,
  input  logic                  csr_restore_mret_i,
  input  logic                  csr_restore_dret_i,
  input  ibex_pkg::exc_cause_t  csr_save_cause_i,
  input  ibex_pkg::exc_cause_t  csr_mcause_i,
  input  logic [31:0]           csr_mtval_i,
  output logic                  illegal_csr_insn_o,

  output logic                  double_fault_seen_o,

  input  logic                  instr_ret_i,
  input  logic                  instr_ret_compressed_i,
  input  logic                  instr_ret_spec_i,
  input  logic                  instr_ret_compressed_spec_i,
  input  logic                  iside_wait_i,
  input  logic                  jump_i,
  input  logic                  branch_i,
  input  logic                  branch_taken_i,
  input  logic                  instr_multicycle_i,
  input  logic                  lsu_busy_i
);

  import ibex_pkg::*;

  localparam int unsigned NUM_HPM_COUNTERS = MHPMCounterNum;
  localparam int unsigned MAX_HPM_COUNTERS = 29;

  // MCOUNTINHIBIT mask
  logic [31:0] mcountinhibit_mask;

  // CSR storage
  logic [31:0] mstatus_q, mstatus_d;
  logic [31:0] mie_q, mie_d;
  logic [31:0] mtvec_q, mtvec_d;
  logic [31:0] mscratch_q, mscratch_d;
  logic [31:0] mepc_q, mepc_d;
  logic [31:0] mcause_q, mcause_d;
  logic [31:0] mtval_q, mtval_d;
  logic [31:0] mip_q, mip_d;
  logic [31:0] mcountinhibit_q, mcountinhibit_d;
  logic [31:0] mseccfg_q, mseccfg_d;
  logic [31:0] cpuctrl_q, cpuctrl_d;

  logic [31:0] dcsr_q, dcsr_d;
  logic [31:0] dpc_q, dpc_d;
  logic [31:0] dscratch0_q, dscratch0_d;
  logic [31:0] dscratch1_q, dscratch1_d;

  logic [31:0] mhpm_event   [32];
  logic [31:0] mhpm_event_d [32];

  pmp_cfg_t            pmpcfg  [PMP_MAX_REGIONS];
  pmp_cfg_t            pmpcfg_d[PMP_MAX_REGIONS];
  logic [PMP_ADDR_MSB:0] pmpaddr  [PMP_MAX_REGIONS];
  logic [PMP_ADDR_MSB:0] pmpaddr_d[PMP_MAX_REGIONS];

  logic [63:0] mcycle_counter, mcycle_counter_d;
  logic [63:0] minstret_counter, minstret_counter_d;
  logic [63:0] mhpm_counter   [MAX_HPM_COUNTERS];
  logic [63:0] mhpm_counter_d [MAX_HPM_COUNTERS];

  // Write control
  logic        csr_wr;
  logic [31:0] csr_rdata;
  logic        illegal_csr;

  assign csr_wr = csr_access_i & csr_op_en_i & (csr_op_i != CSR_OP_READ);

  assign mcountinhibit_mask = (~(((NUM_HPM_COUNTERS > 0) ? ((32'h1 << NUM_HPM_COUNTERS) - 1) : 32'h0) << 3)) | 32'h2;

  // =========================================================================
  // Read data mux
  // =========================================================================
  always_comb begin
    csr_rdata = 32'h0;
    illegal_csr = 1'b0;

    unique case (csr_addr_i)
      CSR_MVENDORID:  csr_rdata = CsrMvendorId;
      CSR_MARCHID:    csr_rdata = 32'h0000_0000;
      CSR_MIMPID:     csr_rdata = CsrMimpId;
      CSR_MHARTID:    csr_rdata = hart_id_i;
      CSR_MSTATUS:    csr_rdata = mstatus_q;
      CSR_MISA:       csr_rdata = MISA_VALUE;
      CSR_MIE:        csr_rdata = mie_q;
      CSR_MTVEC:      csr_rdata = mtvec_q;
      CSR_MSCRATCH:   csr_rdata = mscratch_q;
      CSR_MEPC:       csr_rdata = mepc_q;
      CSR_MCAUSE:     csr_rdata = mcause_q;
      CSR_MTVAL:      csr_rdata = mtval_q;
      CSR_MIP:        csr_rdata = mip_q;
      CSR_MCOUNTINHIBIT: csr_rdata = mcountinhibit_q;

      CSR_CPUCTRL:    csr_rdata = cpuctrl_q;
      CSR_MSECCFG:    csr_rdata = mseccfg_q;
      CSR_MSECCFGH:   csr_rdata = 32'h0;

      CSR_DCSR:       csr_rdata = DbgTriggerEn ? dcsr_q : 32'h0;
      CSR_DPC:        csr_rdata = DbgTriggerEn ? dpc_q : 32'h0;
      CSR_DSCRATCH0:  csr_rdata = DbgTriggerEn ? dscratch0_q : 32'h0;
      CSR_DSCRATCH1:  csr_rdata = DbgTriggerEn ? dscratch1_q : 32'h0;

      CSR_MCYCLE:     csr_rdata = mcycle_counter[31:0];
      CSR_MINSTRET:   csr_rdata = minstret_counter[31:0];
      CSR_MCYCLEH:    csr_rdata = mcycle_counter[63:32];
      CSR_MINSTRETH:  csr_rdata = minstret_counter[63:32];

      CSR_MHPMEVENT3, CSR_MHPMEVENT4, CSR_MHPMEVENT5,
      CSR_MHPMEVENT6, CSR_MHPMEVENT7, CSR_MHPMEVENT8,
      CSR_MHPMEVENT9, CSR_MHPMEVENT10, CSR_MHPMEVENT11,
      CSR_MHPMEVENT12, CSR_MHPMEVENT13, CSR_MHPMEVENT14,
      CSR_MHPMEVENT15, CSR_MHPMEVENT16, CSR_MHPMEVENT17,
      CSR_MHPMEVENT18, CSR_MHPMEVENT19, CSR_MHPMEVENT20,
      CSR_MHPMEVENT21, CSR_MHPMEVENT22, CSR_MHPMEVENT23,
      CSR_MHPMEVENT24, CSR_MHPMEVENT25, CSR_MHPMEVENT26,
      CSR_MHPMEVENT27, CSR_MHPMEVENT28, CSR_MHPMEVENT29,
      CSR_MHPMEVENT30, CSR_MHPMEVENT31: begin
        int idx = int'(csr_addr_i) - int'(CSR_MHPMEVENT3);
        if (idx < MAX_HPM_COUNTERS && idx < NUM_HPM_COUNTERS)
          csr_rdata = mhpm_event[idx];
        else
          csr_rdata = 32'h0;
      end

      CSR_MHPMCOUNTER3, CSR_MHPMCOUNTER4, CSR_MHPMCOUNTER5,
      CSR_MHPMCOUNTER6, CSR_MHPMCOUNTER7, CSR_MHPMCOUNTER8,
      CSR_MHPMCOUNTER9, CSR_MHPMCOUNTER10, CSR_MHPMCOUNTER11,
      CSR_MHPMCOUNTER12, CSR_MHPMCOUNTER13, CSR_MHPMCOUNTER14,
      CSR_MHPMCOUNTER15, CSR_MHPMCOUNTER16, CSR_MHPMCOUNTER17,
      CSR_MHPMCOUNTER18, CSR_MHPMCOUNTER19, CSR_MHPMCOUNTER20,
      CSR_MHPMCOUNTER21, CSR_MHPMCOUNTER22, CSR_MHPMCOUNTER23,
      CSR_MHPMCOUNTER24, CSR_MHPMCOUNTER25, CSR_MHPMCOUNTER26,
      CSR_MHPMCOUNTER27, CSR_MHPMCOUNTER28, CSR_MHPMCOUNTER29,
      CSR_MHPMCOUNTER30, CSR_MHPMCOUNTER31: begin
        int idx = int'(csr_addr_i) - int'(CSR_MHPMCOUNTER3);
        if (idx < MAX_HPM_COUNTERS && idx < NUM_HPM_COUNTERS)
          csr_rdata = mhpm_counter[idx][31:0];
        else
          csr_rdata = 32'h0;
      end

      CSR_MHPMCOUNTER3H, CSR_MHPMCOUNTER4H, CSR_MHPMCOUNTER5H,
      CSR_MHPMCOUNTER6H, CSR_MHPMCOUNTER7H, CSR_MHPMCOUNTER8H,
      CSR_MHPMCOUNTER9H, CSR_MHPMCOUNTER10H, CSR_MHPMCOUNTER11H,
      CSR_MHPMCOUNTER12H, CSR_MHPMCOUNTER13H, CSR_MHPMCOUNTER14H,
      CSR_MHPMCOUNTER15H, CSR_MHPMCOUNTER16H, CSR_MHPMCOUNTER17H,
      CSR_MHPMCOUNTER18H, CSR_MHPMCOUNTER19H, CSR_MHPMCOUNTER20H,
      CSR_MHPMCOUNTER21H, CSR_MHPMCOUNTER22H, CSR_MHPMCOUNTER23H,
      CSR_MHPMCOUNTER24H, CSR_MHPMCOUNTER25H, CSR_MHPMCOUNTER26H,
      CSR_MHPMCOUNTER27H, CSR_MHPMCOUNTER28H, CSR_MHPMCOUNTER29H,
      CSR_MHPMCOUNTER30H, CSR_MHPMCOUNTER31H: begin
        int idx = int'(csr_addr_i) - int'(CSR_MHPMCOUNTER3H);
        if (idx < MAX_HPM_COUNTERS && idx < NUM_HPM_COUNTERS)
          csr_rdata = mhpm_counter[idx][63:32];
        else
          csr_rdata = 32'h0;
      end

      CSR_PMPCFG0, CSR_PMPCFG1, CSR_PMPCFG2, CSR_PMPCFG3: begin
        int idx = int'(csr_addr_i) - int'(CSR_PMPCFG0);
        if (PMPEnable && (idx < (PMPNumRegions + 3) / 4))
          csr_rdata = pmpcfg[idx];
        else
          csr_rdata = 32'h0;
      end

      CSR_PMPADDR0, CSR_PMPADDR1, CSR_PMPADDR2, CSR_PMPADDR3,
      CSR_PMPADDR4, CSR_PMPADDR5, CSR_PMPADDR6, CSR_PMPADDR7,
      CSR_PMPADDR8, CSR_PMPADDR9, CSR_PMPADDR10, CSR_PMPADDR11,
      CSR_PMPADDR12, CSR_PMPADDR13, CSR_PMPADDR14, CSR_PMPADDR15: begin
        int idx = int'(csr_addr_i) - int'(CSR_PMPADDR0);
        if (PMPEnable && (idx < PMPNumRegions))
          csr_rdata = pmpaddr[idx][31:0];
        else
          csr_rdata = 32'h0;
      end

      default: begin
        csr_rdata = 32'h0;
        illegal_csr = 1'b1;
      end
    endcase
  end

  assign csr_rdata_o = csr_rdata;
  assign illegal_csr_insn_o = illegal_csr & csr_access_i;

  // =========================================================================
  // Combinational register update
  // =========================================================================
  always_comb begin
    mstatus_d = mstatus_q;
    mie_d = mie_q;
    mtvec_d = mtvec_q;
    mscratch_d = mscratch_q;
    mepc_d = mepc_q;
    mcause_d = mcause_q;
    mtval_d = mtval_q;
    mip_d = mip_q;
    mcountinhibit_d = mcountinhibit_q;
    mseccfg_d = mseccfg_q;
    cpuctrl_d = cpuctrl_q;
    dcsr_d = dcsr_q;
    dpc_d = dpc_q;
    dscratch0_d = dscratch0_q;
    dscratch1_d = dscratch1_q;

    mcycle_counter_d = mcycle_counter + 64'd1;
    minstret_counter_d = minstret_counter;

    for (int i = 0; i < MAX_HPM_COUNTERS; i++) begin
      mhpm_counter_d[i] = mhpm_counter[i];
      mhpm_event_d[i] = mhpm_event[i];
    end
    for (int i = 0; i < PMP_MAX_REGIONS; i++) begin
      pmpcfg_d[i] = pmpcfg[i];
      pmpaddr_d[i] = pmpaddr[i];
    end
  end

  // CSR write logic
  always_comb begin
    if (csr_wr) begin
      unique case (csr_addr_i)
        CSR_MSTATUS:   mstatus_d = csr_op_result(mstatus_q, csr_wdata_i, csr_op_i, 32'h0000_1888);
        CSR_MIE:       mie_d = csr_op_result(mie_q, csr_wdata_i, csr_op_i, 32'h0000_0888);
        CSR_MTVEC:     mtvec_d = csr_op_result(mtvec_q, csr_wdata_i, csr_op_i, 32'hFFFFFFFE);
        CSR_MSCRATCH:  mscratch_d = csr_op_result(mscratch_q, csr_wdata_i, csr_op_i, 32'h00000000);
        CSR_MEPC:      mepc_d = csr_op_result(mepc_q, csr_wdata_i, csr_op_i, 32'h00000000);
        CSR_MCAUSE:    mcause_d = csr_op_result(mcause_q, csr_wdata_i, csr_op_i, 32'h80000000);
        CSR_MTVAL:     mtval_d = csr_op_result(mtval_q, csr_wdata_i, csr_op_i, 32'h00000000);
        CSR_MIP:       ; // Read-only for software
        CSR_MCOUNTINHIBIT: mcountinhibit_d = csr_op_warl(mcountinhibit_q, csr_wdata_i, csr_op_i, mcountinhibit_mask);
        CSR_CPUCTRL:   cpuctrl_d = csr_op_result(cpuctrl_q, csr_wdata_i, csr_op_i, 32'h00000007);
        CSR_MSECCFG:   mseccfg_d = csr_op_mseccfg(mseccfg_q, csr_wdata_i, csr_op_i);
        CSR_MSECCFGH:  ; // Ignore writes

        CSR_DCSR:      if (DbgTriggerEn) dcsr_d = csr_op_result(dcsr_q, csr_wdata_i, csr_op_i, 32'h00000000);
        CSR_DPC:       if (DbgTriggerEn) dpc_d = csr_op_result(dpc_q, csr_wdata_i, csr_op_i, 32'h00000000);
        CSR_DSCRATCH0: if (DbgTriggerEn) dscratch0_d = csr_op_result(dscratch0_q, csr_wdata_i, csr_op_i, 32'h00000000);
        CSR_DSCRATCH1: if (DbgTriggerEn) dscratch1_d = csr_op_result(dscratch1_q, csr_wdata_i, csr_op_i, 32'h00000000);

        CSR_MCYCLE:     mcycle_counter_d[31:0]  = csr_op_result(mcycle_counter[31:0], csr_wdata_i, csr_op_i, 32'h00000000);
        CSR_MINSTRET:   minstret_counter_d[31:0] = csr_op_result(minstret_counter[31:0], csr_wdata_i, csr_op_i, 32'h00000000);
        CSR_MCYCLEH:    mcycle_counter_d[63:32]  = csr_op_result(mcycle_counter[63:32], csr_wdata_i, csr_op_i, 32'h00000000);
        CSR_MINSTRETH:  minstret_counter_d[63:32] = csr_op_result(minstret_counter[63:32], csr_wdata_i, csr_op_i, 32'h00000000);

        CSR_MHPMEVENT3, CSR_MHPMEVENT4, CSR_MHPMEVENT5,
        CSR_MHPMEVENT6, CSR_MHPMEVENT7, CSR_MHPMEVENT8,
        CSR_MHPMEVENT9, CSR_MHPMEVENT10, CSR_MHPMEVENT11,
        CSR_MHPMEVENT12, CSR_MHPMEVENT13, CSR_MHPMEVENT14,
        CSR_MHPMEVENT15, CSR_MHPMEVENT16, CSR_MHPMEVENT17,
        CSR_MHPMEVENT18, CSR_MHPMEVENT19, CSR_MHPMEVENT20,
        CSR_MHPMEVENT21, CSR_MHPMEVENT22, CSR_MHPMEVENT23,
        CSR_MHPMEVENT24, CSR_MHPMEVENT25, CSR_MHPMEVENT26,
        CSR_MHPMEVENT27, CSR_MHPMEVENT28, CSR_MHPMEVENT29,
        CSR_MHPMEVENT30, CSR_MHPMEVENT31: begin
          int idx = int'(csr_addr_i) - int'(CSR_MHPMEVENT3);
          if (idx < MAX_HPM_COUNTERS && idx < NUM_HPM_COUNTERS)
            mhpm_event_d[idx] = csr_op_warl(mhpm_event[idx], csr_wdata_i, csr_op_i, 32'h00000000);
        end

        CSR_MHPMCOUNTER3, CSR_MHPMCOUNTER4, CSR_MHPMCOUNTER5,
        CSR_MHPMCOUNTER6, CSR_MHPMCOUNTER7, CSR_MHPMCOUNTER8,
        CSR_MHPMCOUNTER9, CSR_MHPMCOUNTER10, CSR_MHPMCOUNTER11,
        CSR_MHPMCOUNTER12, CSR_MHPMCOUNTER13, CSR_MHPMCOUNTER14,
        CSR_MHPMCOUNTER15, CSR_MHPMCOUNTER16, CSR_MHPMCOUNTER17,
        CSR_MHPMCOUNTER18, CSR_MHPMCOUNTER19, CSR_MHPMCOUNTER20,
        CSR_MHPMCOUNTER21, CSR_MHPMCOUNTER22, CSR_MHPMCOUNTER23,
        CSR_MHPMCOUNTER24, CSR_MHPMCOUNTER25, CSR_MHPMCOUNTER26,
        CSR_MHPMCOUNTER27, CSR_MHPMCOUNTER28, CSR_MHPMCOUNTER29,
        CSR_MHPMCOUNTER30, CSR_MHPMCOUNTER31: begin
          int idx = int'(csr_addr_i) - int'(CSR_MHPMCOUNTER3);
          if (idx < MAX_HPM_COUNTERS && idx < NUM_HPM_COUNTERS)
            mhpm_counter_d[idx][31:0] = csr_op_warl(mhpm_counter[idx][31:0], csr_wdata_i, csr_op_i, get_counter_mask_low());
        end

        CSR_MHPMCOUNTER3H, CSR_MHPMCOUNTER4H, CSR_MHPMCOUNTER5H,
        CSR_MHPMCOUNTER6H, CSR_MHPMCOUNTER7H, CSR_MHPMCOUNTER8H,
        CSR_MHPMCOUNTER9H, CSR_MHPMCOUNTER10H, CSR_MHPMCOUNTER11H,
        CSR_MHPMCOUNTER12H, CSR_MHPMCOUNTER13H, CSR_MHPMCOUNTER14H,
        CSR_MHPMCOUNTER15H, CSR_MHPMCOUNTER16H, CSR_MHPMCOUNTER17H,
        CSR_MHPMCOUNTER18H, CSR_MHPMCOUNTER19H, CSR_MHPMCOUNTER20H,
        CSR_MHPMCOUNTER21H, CSR_MHPMCOUNTER22H, CSR_MHPMCOUNTER23H,
        CSR_MHPMCOUNTER24H, CSR_MHPMCOUNTER25H, CSR_MHPMCOUNTER26H,
        CSR_MHPMCOUNTER27H, CSR_MHPMCOUNTER28H, CSR_MHPMCOUNTER29H,
        CSR_MHPMCOUNTER30H, CSR_MHPMCOUNTER31H: begin
          int idx = int'(csr_addr_i) - int'(CSR_MHPMCOUNTER3H);
          if (idx < MAX_HPM_COUNTERS && idx < NUM_HPM_COUNTERS)
            mhpm_counter_d[idx][63:32] = csr_op_warl(mhpm_counter[idx][63:32], csr_wdata_i, csr_op_i, get_counter_mask_high());
        end

        CSR_PMPCFG0, CSR_PMPCFG1, CSR_PMPCFG2, CSR_PMPCFG3: begin
          int idx = int'(csr_addr_i) - int'(CSR_PMPCFG0);
          if (PMPEnable && (idx < (PMPNumRegions + 3) / 4))
            pmpcfg_d[idx] = csr_op_pmpcfg(pmpcfg[idx], csr_wdata_i, csr_op_i, idx);
        end

        CSR_PMPADDR0, CSR_PMPADDR1, CSR_PMPADDR2, CSR_PMPADDR3,
        CSR_PMPADDR4, CSR_PMPADDR5, CSR_PMPADDR6, CSR_PMPADDR7,
        CSR_PMPADDR8, CSR_PMPADDR9, CSR_PMPADDR10, CSR_PMPADDR11,
        CSR_PMPADDR12, CSR_PMPADDR13, CSR_PMPADDR14, CSR_PMPADDR15: begin
          int idx = int'(csr_addr_i) - int'(CSR_PMPADDR0);
          if (PMPEnable && (idx < PMPNumRegions))
            pmpaddr_d[idx] = csr_op_pmpaddr(pmpaddr[idx], csr_wdata_i, csr_op_i, idx);
        end

        default: ;
      endcase
    end
  end

  // Mcycle always increments
  always_comb begin
    if (!mcountinhibit_q[0] && !is_csr_wr_addr(CSR_MCYCLE) && !is_csr_wr_addr(CSR_MCYCLEH))
      mcycle_counter_d = mcycle_counter + 64'd1;
  end

  // =========================================================================
  // Sequential flops
  // =========================================================================
  always_ff @(posedge clk_i or negedge rst_ni) begin
    if (!rst_ni) begin
      mstatus_q       <= 32'h0000_1800;
      mie_q           <= 32'h0;
      mtvec_q         <= 32'h0;
      mscratch_q      <= 32'h0;
      mepc_q          <= 32'h0;
      mcause_q        <= 32'h0;
      mtval_q         <= 32'h0;
      mip_q           <= 32'h0;
      mcountinhibit_q <= 32'h0;
      mseccfg_q       <= 32'h0;
      cpuctrl_q       <= 32'h0;
      dcsr_q          <= 32'h0;
      dpc_q           <= 32'h0;
      dscratch0_q     <= 32'h0;
      dscratch1_q     <= 32'h0;
      mcycle_counter   <= 64'h0;
      minstret_counter <= 64'h0;
      for (int i = 0; i < MAX_HPM_COUNTERS; i++) begin
        mhpm_counter[i] <= 64'h0;
        mhpm_event[i]   <= 32'h1 << i;
      end
      for (int i = 0; i < PMP_MAX_REGIONS; i++) begin
        pmpcfg[i]  <= 8'h0;
        pmpaddr[i] <= '0;
      end
    end else begin
      mstatus_q       <= mstatus_d;
      mie_q           <= mie_d;
      mtvec_q         <= mtvec_d;
      mscratch_q      <= mscratch_d;
      mepc_q          <= mepc_d;
      mcause_q        <= mcause_d;
      mtval_q         <= mtval_d;
      mip_q           <= mip_d;
      mcountinhibit_q <= mcountinhibit_d;
      mseccfg_q       <= mseccfg_d;
      cpuctrl_q       <= cpuctrl_d;
      dcsr_q          <= dcsr_d;
      dpc_q           <= dpc_d;
      dscratch0_q     <= dscratch0_d;
      dscratch1_q     <= dscratch1_d;
      mcycle_counter   <= mcycle_counter_d;
      minstret_counter <= minstret_counter_d;
      for (int i = 0; i < MAX_HPM_COUNTERS; i++) begin
        mhpm_counter[i] <= mhpm_counter_d[i];
        mhpm_event[i]   <= mhpm_event_d[i];
      end
      for (int i = 0; i < PMP_MAX_REGIONS; i++) begin
        pmpcfg[i]  <= pmpcfg_d[i];
        pmpaddr[i] <= pmpaddr_d[i];
      end
    end
  end

  // =========================================================================
  // Output assignments
  // =========================================================================
  assign priv_mode_id_o  = IbexMuBiOn;
  assign priv_mode_lsu_o = IbexMuBiOn;

  assign csr_mtvec_o = mtvec_q;
  assign csr_mstatus_mie_o = mstatus_q[3];
  assign csr_mstatus_tw_o  = mstatus_q[21];
  assign csr_mepc_o  = mepc_q;
  assign csr_mtval_o = mtval_q;
  assign csr_depc_o  = dpc_q;

  assign irq_pending_o = (mie_q & mip_q) != 32'h0;
  assign irqs_o.irq_software = irq_software_i;
  assign irqs_o.irq_timer    = irq_timer_i;
  assign irqs_o.irq_external = irq_external_i;
  assign irqs_o.irq_fast     = irq_fast_i;
  assign irqs_o.irq_nm       = nmi_mode_i;

  assign data_ind_timing_o     = cpuctrl_q[1];
  assign dummy_instr_en_o      = cpuctrl_q[2];
  assign dummy_instr_mask_o    = 3'b111;
  assign dummy_instr_seed_en_o = cpuctrl_q[2];
  assign dummy_instr_seed_o    = 32'h0;
  assign icache_enable_o       = cpuctrl_q[0];

  assign csr_shadow_err_o  = 1'b0;
  assign debug_single_step_o = 1'b0;
  assign debug_ebreakm_o   = 1'b0;
  assign debug_ebreaku_o   = 1'b0;
  assign trigger_match_o   = 1'b0;
  assign double_fault_seen_o = 1'b0;

  // PMP output
  for (genvar i = 0; i < PMP_MAX_REGIONS; i++) begin : g_pmp_out
    assign csr_pmp_cfg_o[i] = pmpcfg[i];
    assign csr_pmp_addr_o[i] = pmpaddr[i];
  end
  assign csr_pmp_mseccfg_o = mseccfg_q;

  // =========================================================================
  // Helper functions
  // =========================================================================

  function automatic logic is_csr_wr_addr(input csr_num_e addr);
    return csr_wr && (csr_addr_i == addr);
  endfunction

  function automatic logic [31:0] csr_op_result(
      input logic [31:0] cur_val, wdata, input csr_op_e op, input logic [31:0] lock_mask);
    unique case (op)
      CSR_OP_WRITE: return (cur_val & lock_mask) | (wdata & ~lock_mask);
      CSR_OP_SET:   return cur_val | (wdata & ~lock_mask);
      CSR_OP_CLEAR: return cur_val & (~wdata | lock_mask);
      default:      return cur_val;
    endcase
  endfunction

  function automatic logic [31:0] csr_op_warl(
      input logic [31:0] cur_val, wdata, input csr_op_e op, input logic [31:0] lock_mask);
    unique case (op)
      CSR_OP_WRITE: return wdata & ~lock_mask;
      CSR_OP_SET:   return cur_val | (wdata & ~lock_mask);
      CSR_OP_CLEAR: return cur_val & (~wdata | lock_mask);
      default:      return cur_val;
    endcase
  endfunction

  function automatic logic [31:0] csr_op_mseccfg(
      input logic [31:0] cur_val, wdata, input csr_op_e op);
    logic [31:0] lock_mask;
    lock_mask = 32'hFFFFFFF8;
    if (!cur_val[2] && mseccfg_has_pmp_locked())
      lock_mask[2] = 1'b1;
    if (cur_val[1])
      lock_mask[1] = 1'b1;
    if (cur_val[0])
      lock_mask[0] = 1'b1;
    return csr_op_result(cur_val, wdata, op, lock_mask);
  endfunction

  function automatic logic mseccfg_has_pmp_locked();
    for (int i = 0; i < PMP_MAX_REGIONS; i++) begin
      if (PMPEnable && (i < PMPNumRegions)) begin
        if ((pmpcfg[i/4] >> (8*(i%4))) & 8'h80)
          return 1'b1;
      end
    end
    return 1'b0;
  endfunction

  function automatic logic [7:0] csr_op_pmpcfg(
      input logic [7:0] cur_val, input logic [31:0] wdata, input csr_op_e op, input int cfg_idx);
    logic [31:0] cur32, wdata32, result32;
    logic [31:0] lock_mask;

    cur32 = {24'h0, cur_val};
    wdata32 = wdata;

    lock_mask = 32'h0;
    if (cur_val[7])  lock_mask[7:0] = 8'hFF;

    if (mseccfg_q[2]) lock_mask = 32'h0;

    result32 = csr_op_result(cur32, wdata32, op, lock_mask);

    result32 = handle_pmpcfg_reserved(result32);

    return result32[7:0];
  endfunction

  function automatic logic [31:0] handle_pmpcfg_reserved(input logic [31:0] cfg_val);
    logic [31:0] result;
    result = cfg_val & 32'h9F9F9F9F;

    if (mseccfg_q[0])
      return result;

    for (int i = 0; i < 4; i++) begin
      if ((result >> (8 * i)) & 8'h03 == 8'h02)
        result &= ~(32'h03 << (8 * i));
    end

    return result;
  endfunction

  function automatic logic [PMP_ADDR_MSB:0] csr_op_pmpaddr(
      input logic [PMP_ADDR_MSB:0] cur_val, input logic [31:0] wdata, input csr_op_e op, input int addr_idx);
    logic [31:0] cur32, wdata32, result32;
    logic [31:0] lock_mask;
    logic [7:0]  cfg_val, cfg_plus1_val;

    cur32 = cur_val;
    wdata32 = wdata;

    cfg_val = pmpcfg[addr_idx / 4];
    cfg_val = (cfg_val >> (8 * (addr_idx & 3))) & 8'hFF;

    cfg_plus1_val = (addr_idx < 15) ? pmpcfg[(addr_idx + 1) / 4] : 8'h0;
    cfg_plus1_val = (cfg_plus1_val >> (8 * ((addr_idx + 1) & 3))) & 8'hFF;

    if ((cfg_val[7]) || (cfg_plus1_val[4:1] == 4'b0100))
      lock_mask = 32'hFFFFFFFF;
    else
      lock_mask = 32'h0;

    result32 = csr_op_result(cur32, wdata32, op, lock_mask);
    return PMP_ADDR_MSB'(result32);
  endfunction

  function automatic logic [31:0] get_counter_mask_low();
    if (MHPMCounterWidth >= 64) return 32'h00000000;
    else if (MHPMCounterWidth >= 32) return 32'h00000000;
    else return ~((32'h1 << MHPMCounterWidth) - 1);
  endfunction

  function automatic logic [31:0] get_counter_mask_high();
    if (MHPMCounterWidth >= 64) return 32'h00000000;
    else if (MHPMCounterWidth > 32) return ~((32'h1 << (MHPMCounterWidth - 32)) - 1);
    else return 32'hFFFFFFFF;
  endfunction

  `ASSERT_KNOWN(MHPMCounterWidthCheck, MHPMCounterWidth >= 32)

endmodule

