`include "prim_assert.sv"

module ibex_cs_registers #(
  parameter bit               DbgTriggerEn      = 1'b0,
  parameter int unsigned      DbgHwBreakNum     = 1,
  parameter bit               DataIndTiming     = 1'b0,
  parameter bit               DummyInstructions = 1'b0,
  parameter bit               ShadowCSR         = 1'b0,
  parameter bit               ICache            = 1'b0,
  parameter int unsigned      MHPMCounterNum    = 8,
  parameter int unsigned      MHPMCounterWidth  = 40,
  parameter bit               PMPEnable         = 1'b0,
  parameter int unsigned      PMPGranularity    = 0,
  parameter int unsigned      PMPNumRegions     = 4,
  parameter ibex_pkg::pmp_cfg_t     PMPRstCfg   [ibex_pkg::PMP_MAX_REGIONS] = '{default:'0},
  parameter logic [ibex_pkg::PMP_ADDR_MSB:0] PMPRstAddr [ibex_pkg::PMP_MAX_REGIONS] = '{default:'0},
  parameter ibex_pkg::pmp_mseccfg_t PMPRstMseccfg = '0,
  parameter bit               RV32E             = 1'b0,
  parameter ibex_pkg::rv32m_e RV32M             = ibex_pkg::RV32MFast,
  parameter ibex_pkg::rv32b_e RV32B             = ibex_pkg::RV32BNone,
  parameter logic [31:0]      CsrMvendorId     = 32'b0,
  parameter logic [31:0]      CsrMimpId        = 32'b0
) (
  input  logic                  clk_i,
  input  logic                  rst_ni,
  input  logic [31:0]           hart_id_i,
  output ibex_pkg::ibex_mubi_t  priv_mode_id_o,
  output ibex_pkg::ibex_mubi_t  priv_mode_lsu_o,
  output logic [31:0]           csr_mtvec_o,
  input  logic                  csr_mtvec_init_i,
  input  logic [31:0]           boot_addr_i,
  input  logic                  csr_access_i,
  input  ibex_pkg::csr_num_e    csr_addr_i,
  input  logic [31:0]           csr_wdata_i,
  input  ibex_pkg::csr_op_e     csr_op_i,
  input  logic                  csr_op_en_i,
  output logic [31:0]           csr_rdata_o,
  input  logic                  irq_software_i,
  input  logic                  irq_timer_i,
  input  logic                  irq_external_i,
  input  logic [14:0]           irq_fast_i,
  input  logic                  nmi_mode_i,
  output logic                  irq_pending_o,
  output ibex_pkg::irqs_t       irqs_o,
  output logic                  csr_mstatus_mie_o,
  output logic                  csr_mstatus_tw_o,
  output logic [31:0]           csr_mepc_o,
  output logic [31:0]           csr_mtval_o,
  output ibex_pkg::pmp_cfg_t                      csr_pmp_cfg_o     [ibex_pkg::PMP_MAX_REGIONS],
  output logic [ibex_pkg::PMP_ADDR_MSB:0]         csr_pmp_addr_o    [ibex_pkg::PMP_MAX_REGIONS],
  output ibex_pkg::pmp_mseccfg_t                  csr_pmp_mseccfg_o,
  output logic [31:0]           csr_depc_o,
  input  logic                  debug_mode_i,
  input  logic                  debug_mode_entering_i,
  input  ibex_pkg::exc_cause_t  debug_cause_i,
  input  logic                  debug_csr_save_i,
  output logic                  debug_single_step_o,
  output logic                  debug_ebreakm_o,
  output logic                  debug_ebreaku_o,
  output logic                  trigger_match_o,
  input  logic [31:0]           pc_if_i,
  input  logic [31:0]           pc_id_i,
  input  logic [31:0]           pc_wb_i,
  output logic                  data_ind_timing_o,
  output logic                  dummy_instr_en_o,
  output logic [2:0]            dummy_instr_mask_o,
  output logic                  dummy_instr_seed_en_o,
  output logic [31:0]           dummy_instr_seed_o,
  output logic                  icache_enable_o,
  output logic                  csr_shadow_err_o,
  input  logic                  ic_scr_key_valid_i,
  input  logic                  csr_save_if_i,
  input  logic                  csr_save_id_i,
  input  logic                  csr_save_wb_i,
  input  logic                  csr_restore_mret_i,
  input  logic                  csr_restore_dret_i,
  input  ibex_pkg::exc_cause_t  csr_save_cause_i,
  input  ibex_pkg::exc_cause_t  csr_mcause_i,
  input  logic [31:0]           csr_mtval_i,
  output logic                  illegal_csr_insn_o,
  output logic                  double_fault_seen_o,
  input  logic                  instr_ret_i,
  input  logic                  instr_ret_compressed_i,
  input  logic                  instr_ret_spec_i,
  input  logic                  instr_ret_compressed_spec_i,
  input  logic                  iside_wait_i,
  input  logic                  jump_i,
  input  logic                  branch_i,
  input  logic                  branch_taken_i,
  input  logic                  instr_multicycle_i,
  input  logic                  lsu_busy_i
);

  import ibex_pkg::*;

  localparam int unsigned NUM_HPM_COUNTERS = MHPMCounterNum;
  localparam int unsigned MAX_HPM_COUNTERS = 29;

  logic [31:0] mcountinhibit_mask;

  logic [31:0] mstatus_q, mstatus_d;
  logic [31:0] mie_q, mie_d;
  logic [31:0] mtvec_q, mtvec_d;
  logic [31:0] mscratch_q, mscratch_d;
  logic [31:0] mepc_q, mepc_d;
  logic [31:0] mcause_q, mcause_d;
  logic [31:0] mtval_q, mtval_d;
  logic [31:0] mip_q, mip_d;
  logic [31:0] mcountinhibit_q, mcountinhibit_d;
  logic [31:0] mseccfg_q, mseccfg_d;
  logic [31:0] cpuctrl_q, cpuctrl_d;
  logic [31:0] dcsr_q, dcsr_d;
  logic [31:0] dpc_q, dpc_d;
  logic [31:0] dscratch0_q, dscratch0_d;
  logic [31:0] dscratch1_q, dscratch1_d;

  logic [31:0] mhpm_event   [32];
  logic [31:0] mhpm_event_d [32];

  pmp_cfg_t               pmpcfg  [PMP_MAX_REGIONS];
  pmp_cfg_t               pmpcfg_d[PMP_MAX_REGIONS];
  logic [PMP_ADDR_MSB:0]  pmpaddr  [PMP_MAX_REGIONS];
  logic [PMP_ADDR_MSB:0]  pmpaddr_d[PMP_MAX_REGIONS];

  logic [63:0] mcycle_counter, mcycle_counter_d;
  logic [63:0] minstret_counter, minstret_counter_d;
  logic [63:0] mhpm_counter   [MAX_HPM_COUNTERS];
  logic [63:0] mhpm_counter_d [MAX_HPM_COUNTERS];

  logic        csr_wr;
  logic [31:0] csr_rdata;
  logic        illegal_csr;

  assign csr_wr = csr_access_i & csr_op_en_i & (csr_op_i != CSR_OP_READ);
  assign mcountinhibit_mask = (~(((NUM_HPM_COUNTERS > 0) ? ((32'h1 << NUM_HPM_COUNTERS) - 1) : 32'h0) << 3)) | 32'h2;

  // =========================================================================
  // Read data mux (combinational)
  // =========================================================================
  always_comb begin
    csr_rdata = 32'h0;
    illegal_csr = 1'b0;
    unique case (csr_addr_i)
      CSR_MVENDORID:  csr_rdata = CsrMvendorId;
      CSR_MARCHID:    csr_rdata = 32'h0;
      CSR_MIMPID:     csr_rdata = CsrMimpId;
      CSR_MHARTID:    csr_rdata = hart_id_i;
      CSR_MSTATUS:    csr_rdata = mstatus_q;
      CSR_MISA:       csr_rdata = MISA_VALUE;
      CSR_MIE:        csr_rdata = mie_q;
      CSR_MTVEC:      csr_rdata = mtvec_q;
      CSR_MSCRATCH:   csr_rdata = mscratch_q;
      CSR_MEPC:       csr_rdata = mepc_q;
      CSR_MCAUSE:     csr_rdata = mcause_q;
      CSR_MTVAL:      csr_rdata = mtval_q;
      CSR_MIP:        csr_rdata = mip_q;
      CSR_MCOUNTINHIBIT: csr_rdata = mcountinhibit_q;
      CSR_CPUCTRL:    csr_rdata = cpuctrl_q;
      CSR_MSECCFG:    csr_rdata = mseccfg_q;
      CSR_MSECCFGH:   csr_rdata = 32'h0;
      CSR_DCSR:       csr_rdata = DbgTriggerEn ? dcsr_q : 32'h0;
      CSR_DPC:        csr_rdata = DbgTriggerEn ? dpc_q : 32'h0;
      CSR_DSCRATCH0:  csr_rdata = DbgTriggerEn ? dscratch0_q : 32'h0;
      CSR_DSCRATCH1:  csr_rdata = DbgTriggerEn ? dscratch1_q : 32'h0;
      CSR_MCYCLE:     csr_rdata = mcycle_counter[31:0];
      CSR_MINSTRET:   csr_rdata = minstret_counter[31:0];
      CSR_MCYCLEH:    csr_rdata = mcycle_counter[63:32];
      CSR_MINSTRETH:  csr_rdata = minstret_counter[63:32];
      CSR_MHPMEVENT3, CSR_MHPMEVENT4, CSR_MHPMEVENT5,
      CSR_MHPMEVENT6, CSR_MHPMEVENT7, CSR_MHPMEVENT8,
      CSR_MHPMEVENT9, CSR_MHPMEVENT10, CSR_MHPMEVENT11,
      CSR_MHPMEVENT12, CSR_MHPMEVENT13, CSR_MHPMEVENT14,
      CSR_MHPMEVENT15, CSR_MHPMEVENT16, CSR_MHPMEVENT17,
      CSR_MHPMEVENT18, CSR_MHPMEVENT19, CSR_MHPMEVENT20,
      CSR_MHPMEVENT21, CSR_MHPMEVENT22, CSR_MHPMEVENT23,
      CSR_MHPMEVENT24, CSR_MHPMEVENT25, CSR_MHPMEVENT26,
      CSR_MHPMEVENT27, CSR_MHPMEVENT28, CSR_MHPMEVENT29,
      CSR_MHPMEVENT30, CSR_MHPMEVENT31: begin
        int idx = int'(csr_addr_i) - int'(CSR_MHPMEVENT3);
        if (idx >= 0 && idx < MAX_HPM_COUNTERS && idx < NUM_HPM_COUNTERS)
          csr_rdata = mhpm_event[idx];
      end
      CSR_MHPMCOUNTER3, CSR_MHPMCOUNTER4, CSR_MHPMCOUNTER5,
      CSR_MHPMCOUNTER6, CSR_MHPMCOUNTER7, CSR_MHPMCOUNTER8,
      CSR_MHPMCOUNTER9, CSR_MHPMCOUNTER10, CSR_MHPMCOUNTER11,
      CSR_MHPMCOUNTER12, CSR_MHPMCOUNTER13, CSR_MHPMCOUNTER14,
      CSR_MHPMCOUNTER15, CSR_MHPMCOUNTER16, CSR_MHPMCOUNTER17,
      CSR_MHPMCOUNTER18, CSR_MHPMCOUNTER19, CSR_MHPMCOUNTER20,
      CSR_MHPMCOUNTER21, CSR_MHPMCOUNTER22, CSR_MHPMCOUNTER23,
      CSR_MHPMCOUNTER24, CSR_MHPMCOUNTER25, CSR_MHPMCOUNTER26,
      CSR_MHPMCOUNTER27, CSR_MHPMCOUNTER28, CSR_MHPMCOUNTER29,
      CSR_MHPMCOUNTER30, CSR_MHPMCOUNTER31: begin
        int idx = int'(csr_addr_i) - int'(CSR_MHPMCOUNTER3);
