  output logic                  dummy_instr_en_o,
  output logic [2:0]            dummy_instr_mask_o,
  output logic                  dummy_instr_seed_en_o,
  output logic [31:0]           dummy_instr_seed_o,
  output logic                  icache_enable_o,
  output logic                  csr_shadow_err_o,
  input  logic                  ic_scr_key_valid_i,
  input  logic                  csr_save_if_i,
  input  logic                  csr_save_id_i,
  input  logic                  csr_save_wb_i,
  input  logic                  csr_restore_mret_i,
  input  logic                  csr_restore_dret_i,
  input  ibex_pkg::exc_cause_t  csr_save_cause_i,
  input  ibex_pkg::exc_cause_t  csr_mcause_i,
  input  logic [31:0]           csr_mtval_i,
  output logic                  illegal_csr_insn_o,
  output logic                  double_fault_seen_o,
  input  logic                  instr_ret_i,
  input  logic                  instr_ret_compressed_i,
  input  logic                  instr_ret_spec_i,
  input  logic                  instr_ret_compressed_spec_i,
  input  logic                  iside_wait_i,
  input  logic                  jump_i,
  input  logic                  branch_i,
  input  logic                  branch_taken_i,
  input  logic                  instr_multicycle_i,
  input  logic                  lsu_busy_i
);

  import ibex_pkg::*;

  localparam int unsigned NUM_HPM_COUNTERS = MHPMCounterNum;
  localparam int unsigned MAX_HPM_COUNTERS = 29;

  logic [31:0] mcountinhibit_mask;

  logic [31:0] mstatus_q, mstatus_d;
  logic [31:0] mie_q, mie_d;
  logic [31:0] mtvec_q, mtvec_d;
  logic [31:0] mscratch_q, mscratch_d;
  logic [31:0] mepc_q, mepc_d;
  logic [31:0] mcause_q, mcause_d;
  logic [31:0] mtval_q, mtval_d;
  logic [31:0] mip_q, mip_d;
  logic [31:0] mcountinhibit_q, mcountinhibit_d;
  logic [31:0] mseccfg_q, mseccfg_d;
  logic [31:0] cpuctrl_q, cpuctrl_d;
  logic [31:0] dcsr_q, dcsr_d;
  logic [31:0] dpc_q, dpc_d;
  logic [31:0] dscratch0_q, dscratch0_d;
  logic [31:0] dscratch1_q, dscratch1_d;

  logic [31:0] mhpm_event   [32];
  logic [31:0] mhpm_event_d [32];

  ibex_pkg::pmp_cfg_t               pmpcfg  [ibex_pkg::PMP_MAX_REGIONS];
  ibex_pkg::pmp_cfg_t               pmpcfg_d[ibex_pkg::PMP_MAX_REGIONS];
  logic [ibex_pkg::PMP_ADDR_MSB:0]  pmpaddr  [ibex_pkg::PMP_MAX_REGIONS];
  logic [ibex_pkg::PMP_ADDR_MSB:0]  pmpaddr_d[ibex_pkg::PMP_MAX_REGIONS];

  logic [63:0] mcycle_counter, mcycle_counter_d;
  logic [63:0] minstret_counter, minstret_counter_d;
  logic [63:0] mhpm_counter   [MAX_HPM_COUNTERS];
  logic [63:0] mhpm_counter_d [MAX_HPM_COUNTERS];

  logic        csr_wr;
  logic [31:0] csr_rdata;
  logic        illegal_csr;

  assign csr_wr = csr_access_i & csr_op_en_i & (csr_op_i != CSR_OP_READ);
  assign mcountinhibit_mask = (~(((NUM_HPM_COUNTERS > 0) ? ((32'h1 << NUM_HPM_COUNTERS) - 1) : 32'h0) << 3)) | 32'h2;

  function automatic logic [31:0] fn_csr_op(input logic [31:0] cur, wdata, input csr_op_e op, input logic [31:0] lock_mask);
    case (op)
      CSR_OP_WRITE: return (cur & lock_mask) | (wdata & ~lock_mask);
      CSR_OP_SET:   return cur | (wdata & ~lock_mask);
      CSR_OP_CLEAR: return cur & (~wdata | lock_mask);
      default:      return cur;
    endcase
  endfunction

  function automatic logic [31:0] fn_mseccfg_lock(input logic [31:0] cur_val);
    logic [31:0] lock;
    lock = 32'hFFFFFFF8;
    if (!cur_val[2]) begin
      for (int i = 0; i < ibex_pkg::PMP_MAX_REGIONS; i++) begin
        if (PMPEnable && (i < PMPNumRegions)) begin
          if ((pmpcfg[i/4] >> (8*(i%4))) & 8'h80) begin
            lock[2] = 1'b1;
          end
        end
      end
    end
    if (cur_val[1]) lock[1] = 1'b1;
    if (cur_val[0]) lock[0] = 1'b1;
    return lock;
  endfunction

  // =========================================================================
  // Combined combinational logic for read data and next-state
  // =========================================================================
  always_comb begin
    // Defaults
    mstatus_d = mstatus_q;
    mie_d = mie_q;
    mtvec_d = mtvec_q;
    mscratch_d = mscratch_q;
    mepc_d = mepc_q;
    mcause_d = mcause_q;
    mtval_d = mtval_q;
    mip_d = mip_q;
    mcountinhibit_d = mcountinhibit_q;
    mseccfg_d = mseccfg_q;
    cpuctrl_d = cpuctrl_q;
    dcsr_d = dcsr_q;
    dpc_d = dpc_q;
    dscratch0_d = dscratch0_q;
    dscratch1_d = dscratch1_q;
    mcycle_counter_d = mcycle_counter + 64'd1;
    minstret_counter_d = minstret_counter;
    for (int i = 0; i < MAX_HPM_COUNTERS; i++) begin
      mhpm_counter_d[i] = mhpm_counter[i];
      mhpm_event_d[i] = mhpm_event[i];
    end
    for (int i = 0; i < ibex_pkg::PMP_MAX_REGIONS; i++) begin
      pmpcfg_d[i] = pmpcfg[i];
      pmpaddr_d[i] = pmpaddr[i];
    end

    csr_rdata = 32'h0;
    illegal_csr = 1'b0;

    // Read data mux
    if (csr_addr_i inside {CSR_MVENDORID})
      csr_rdata = CsrMvendorId;
    else if (csr_addr_i inside {CSR_MARCHID})
      csr_rdata = 32'h0;
    else if (csr_addr_i inside {CSR_MIMPID})
      csr_rdata = CsrMimpId;
    else if (csr_addr_i inside {CSR_MHARTID})
      csr_rdata = hart_id_i;
    else if (csr_addr_i inside {CSR_MSTATUS})
      csr_rdata = mstatus_q;
    else if (csr_addr_i inside {CSR_MISA})
      csr_rdata = MISA_VALUE;
    else if (csr_addr_i inside {CSR_MIE})
      csr_rdata = mie_q;
    else if (csr_addr_i inside {CSR_MTVEC})
      csr_rdata = mtvec_q;
    else if (csr_addr_i inside {CSR_MSCRATCH})
      csr_rdata = mscratch_q;
    else if (csr_addr_i inside {CSR_MEPC})
      csr_rdata = mepc_q;
    else if (csr_addr_i inside {CSR_MCAUSE})
      csr_rdata = mcause_q;
    else if (csr_addr_i inside {CSR_MTVAL})
      csr_rdata = mtval_q;
    else if (csr_addr_i inside {CSR_MIP})
      csr_rdata = mip_q;
    else if (csr_addr_i inside {CSR_MCOUNTINHIBIT})
      csr_rdata = mcountinhibit_q;
    else if (csr_addr_i inside {CSR_CPUCTRL})
      csr_rdata = cpuctrl_q;
    else if (csr_addr_i inside {CSR_MSECCFG})
      csr_rdata = mseccfg_q;
    else if (csr_addr_i inside {CSR_MSECCFGH})
      csr_rdata = 32'h0;
    else if (csr_addr_i inside {CSR_DCSR})
      csr_rdata = DbgTriggerEn ? dcsr_q : 32'h0;
    else if (csr_addr_i inside {CSR_DPC})
      csr_rdata = DbgTriggerEn ? dpc_q : 32'h0;
    else if (csr_addr_i inside {CSR_DSCRATCH0})
      csr_rdata = DbgTriggerEn ? dscratch0_q : 32'h0;
    else if (csr_addr_i inside {CSR_DSCRATCH1})
      csr_rdata = DbgTriggerEn ? dscratch1_q : 32'h0;
    else if (csr_addr_i inside {CSR_MCYCLE})
      csr_rdata = mcycle_counter[31:0];
    else if (csr_addr_i inside {CSR_MINSTRET})
      csr_rdata = minstret_counter[31:0];
    else if (csr_addr_i inside {CSR_MCYCLEH})
      csr_rdata = mcycle_counter[63:32];
    else if (csr_addr_i inside {CSR_MINSTRETH})
      csr_rdata = minstret_counter[63:32];
    else if ((csr_addr_i >= CSR_MHPMEVENT3) && (csr_addr_i <= CSR_MHPMEVENT31)) begin
      int idx = int'(csr_addr_i) - int'(CSR_MHPMEVENT3);
      if (idx < MAX_HPM_COUNTERS && idx < NUM_HPM_COUNTERS)
        csr_rdata = mhpm_event[idx];
    end
    else if ((csr_addr_i >= CSR_MHPMCOUNTER3) && (csr_addr_i <= CSR_MHPMCOUNTER31)) begin
      int idx = int'(csr_addr_i) - int'(CSR_MHPMCOUNTER3);
      if (idx < MAX_HPM_COUNTERS && idx < NUM_HPM_COUNTERS)
        csr_rdata = mhpm_counter[idx][31:0];
    end
    else if ((csr_addr_i >= CSR_MHPMCOUNTER3H) && (csr_addr_i <= CSR_MHPMCOUNTER31H)) begin
      int idx = int'(csr_addr_i) - int'(CSR_MHPMCOUNTER3H);
      if (idx < MAX_HPM_COUNTERS && idx < NUM_HPM_COUNTERS)
        csr_rdata = mhpm_counter[idx][63:32];
    end
    else if ((csr_addr_i >= CSR_PMPCFG0) && (csr_addr_i <= CSR_PMPCFG3)) begin
      int idx = int'(csr_addr_i) - int'(CSR_PMPCFG0);
      if (PMPEnable && (idx < (PMPNumRegions + 3) / 4))
        csr_rdata = {24'h0, pmpcfg[idx]};
    end
    else if ((csr_addr_i >= CSR_PMPADDR0) && (csr_addr_i <= CSR_PMPADDR15)) begin
      int idx = int'(csr_addr_i) - int'(CSR_PMPADDR0);
      if (PMPEnable && (idx < PMPNumRegions))
        csr_rdata = pmpaddr[idx][31:0];
    end
    else
      illegal_csr = 1'b1;

    // Write logic
    if (csr_wr) begin
      if (csr_addr_i inside {CSR_MSTATUS})
        mstatus_d = fn_csr_op(mstatus_q, csr_wdata_i, csr_op_i, 32'h0000_1888);
      else if (csr_addr_i inside {CSR_MIE})
        mie_d = fn_csr_op(mie_q, csr_wdata_i, csr_op_i, 32'h0000_0888);
      else if (csr_addr_i inside {CSR_MTVEC})
        mtvec_d = fn_csr_op(mtvec_q, csr_wdata_i, csr_op_i, 32'hFFFFFFFE);
      else if (csr_addr_i inside {CSR_MSCRATCH})
        mscratch_d = fn_csr_op(mscratch_q, csr_wdata_i, csr_op_i, 32'h00000000);
      else if (csr_addr_i inside {CSR_MEPC})
        mepc_d = fn_csr_op(mepc_q, csr_wdata_i, csr_op_i, 32'h00000000);
      else if (csr_addr_i inside {CSR_MCAUSE})
        mcause_d = fn_csr_op(mcause_q, csr_wdata_i, csr_op_i, 32'h80000000);
      else if (csr_addr_i inside {CSR_MTVAL})
        mtval_d = fn_csr_op(mtval_q, csr_wdata_i, csr_op_i, 32'h00000000);
      else if (csr_addr_i inside {CSR_MCOUNTINHIBIT})
        mcountinhibit_d = fn_csr_op(mcountinhibit_q, csr_wdata_i, csr_op_i, mcountinhibit_mask);
      else if (csr_addr_i inside {CSR_CPUCTRL})
        cpuctrl_d = fn_csr_op(cpuctrl_q, csr_wdata_i, csr_op_i, 32'h00000007);
      else if (csr_addr_i inside {CSR_MSECCFG})
        mseccfg_d = fn_csr_op(mseccfg_q, csr_wdata_i, csr_op_i, fn_mseccfg_lock(mseccfg_q));
      else if (csr_addr_i inside {CSR_MSECCFGH})
        ;
      else if (csr_addr_i inside {CSR_DCSR}) begin
        if (DbgTriggerEn) dcsr_d = fn_csr_op(dcsr_q, csr_wdata_i, csr_op_i, 32'h00000000);
      end
      else if (csr_addr_i inside {CSR_DPC}) begin
        if (DbgTriggerEn) dpc_d = fn_csr_op(dpc_q, csr_wdata_i, csr_op_i, 32'h00000000);
      end
      else if (csr_addr_i inside {CSR_DSCRATCH0}) begin
        if (DbgTriggerEn) dscratch0_d = fn_csr_op(dscratch0_q, csr_wdata_i, csr_op_i, 32'h00000000);
      end
      else if (csr_addr_i inside {CSR_DSCRATCH1}) begin
        if (DbgTriggerEn) dscratch1_d = fn_csr_op(dscratch1_q, csr_wdata_i, csr_op_i, 32'h00000000);
      end
      else if (csr_addr_i inside {CSR_MCYCLE})
        mcycle_counter_d[31:0] = fn_csr_op(mcycle_counter[31:0], csr_wdata_i, csr_op_i, 32'h00000000);
      else if (csr_addr_i inside {CSR_MINSTRET})
        minstret_counter_d[31:0] = fn_csr_op(minstret_counter[31:0], csr_wdata_i, csr_op_i, 32'h00000000);
      else if (csr_addr_i inside {CSR_MCYCLEH})
        mcycle_counter_d[63:32] = fn_csr_op(mcycle_counter[63:32], csr_wdata_i, csr_op_i, 32'h00000000);
      else if (csr_addr_i inside {CSR_MINSTRETH})
        minstret_counter_d[63:32] = fn_csr_op(minstret_counter[63:32], csr_wdata_i, csr_op_i, 32'h00000000);
      else if ((csr_addr_i >= CSR_MHPMEVENT3) && (csr_addr_i <= CSR_MHPMEVENT31)) begin
        int idx = int'(csr_addr_i) - int'(CSR_MHPMEVENT3);
        if (idx < MAX_HPM_COUNTERS && idx < NUM_HPM_COUNTERS)
          mhpm_event_d[idx] = fn_csr_op(mhpm_event[idx], csr_wdata_i, csr_op_i, 32'h00000000);
      end
      else if ((csr_addr_i >= CSR_MHPMCOUNTER3) && (csr_addr_i <= CSR_MHPMCOUNTER31)) begin
        int idx = int'(csr_addr_i) - int'(CSR_MHPMCOUNTER3);
        if (idx < MAX_HPM_COUNTERS && idx < NUM_HPM_COUNTERS)
          mhpm_counter_d[idx][31:0] = fn_csr_op(mhpm_counter[idx][31:0], csr_wdata_i, csr_op_i, 32'h00000000);
      end
      else if ((csr_addr_i >= CSR_MHPMCOUNTER3H) && (csr_addr_i <= CSR_MHPMCOUNTER31H)) begin
        int idx = int'(csr_addr_i) - int'(CSR_MHPMCOUNTER3H);
        if (idx < MAX_HPM_COUNTERS && idx < NUM_HPM_COUNTERS)
          mhpm_counter_d[idx][63:32] = fn_csr_op(mhpm_counter[idx][63:32], csr_wdata_i, csr_op_i, 32'h00000000);
      end
      else if ((csr_addr_i >= CSR_PMPCFG0) && (csr_addr_i <= CSR_PMPCFG3)) begin
        int idx = int'(csr_addr_i) - int'(CSR_PMPCFG0);
        if (PMPEnable && (idx < (PMPNumRegions + 3) / 4)) begin
          logic [31:0] cur32, wdata32, res32;
          logic [31:0] lock_mask;
          logic [7:0] lmask;
          lmask = 8'h0;
          if (mseccfg_q[2]) lmask = 8'h0;
          else if (pmpcfg[idx][7]) lmask = 8'hFF;
          cur32 = {24'h0, pmpcfg[idx]};
          wdata32 = csr_wdata_i;
          res32 = fn_csr_op(cur32, wdata32, csr_op_i, {24'h0, lmask});
          res32 = res32 & 32'h9F9F9F9F;
          if (!mseccfg_q[0]) begin
            for (int b = 0; b < 4; b++) begin
              if ((res32 >> (8*b)) & 8'h03 == 8'h02)
                res32 &= ~(32'h03 << (8*b));
            end
          end
          pmpcfg_d[idx] = res32[7:0];
        end
      end
      else if ((csr_addr_i >= CSR_PMPADDR0) && (csr_addr_i <= CSR_PMPADDR15)) begin
        int idx = int'(csr_addr_i) - int'(CSR_PMPADDR0);
        if (PMPEnable && (idx < PMPNumRegions)) begin
          logic [31:0] cur32, wdata32, res32;
          logic [31:0] lock_mask;
          logic [7:0] cfg_cur, cfg_plus1;
          if (PMPEnable && (idx < PMPNumRegions)) begin
            cfg_cur = pmpcfg[idx/4];
            cfg_cur = (cfg_cur >> (8*(idx%4))) & 8'hFF;
            cfg_plus1 = (idx < 15) ? pmpcfg[(idx+1)/4] : 8'h0;
            cfg_plus1 = (cfg_plus1 >> (8*((idx+1)%4))) & 8'hFF;
            if (cfg_cur[7] || (cfg_plus1[4:1] == 4'b0100))
              lock_mask = 32'hFFFFFFFF;
            else
              lock_mask = 32'h0;
          end else
            lock_mask = 32'h0;
          cur32 = pmpaddr[idx][31:0];
          wdata32 = csr_wdata_i;
          res32 = fn_csr_op(cur32, wdata32, csr_op_i, lock_mask);
          pmpaddr_d[idx] = ibex_pkg::PMP_ADDR_MSB'(res32);
        end
      end
    end
  end

  assign csr_rdata_o = csr_rdata;
  assign illegal_csr_insn_o = illegal_csr & csr_access_i;

  // =========================================================================
  // Flops
  // =========================================================================
  always_ff @(posedge clk_i or negedge rst_ni) begin
    if (!rst_ni) begin
      mstatus_q       <= 32'h0000_1800;
      mie_q           <= 32'h0;
      mtvec_q         <= 32'h0;
      mscratch_q      <= 32'h0;
      mepc_q          <= 32'h0;
      mcause_q        <= 32'h0;
      mtval_q         <= 32'h0;
      mip_q           <= 32'h0;
      mcountinhibit_q <= 32'h0;
      mseccfg_q       <= 32'h0;
      cpuctrl_q       <= 32'h0;
      dcsr_q          <= 32'h0;
      dpc_q           <= 32'h0;
      dscratch0_q     <= 32'h0;
      dscratch1_q     <= 32'h0;
      mcycle_counter   <= 64'h0;
      minstret_counter <= 64'h0;
      for (int i = 0; i < MAX_HPM_COUNTERS; i++) begin
        mhpm_counter[i] <= 64'h0;
        mhpm_event[i]   <= 32'h1 << i;
      end
      for (int i = 0; i < ibex_pkg::PMP_MAX_REGIONS; i++) begin
        pmpcfg[i]  <= 8'h0;
        pmpaddr[i] <= '0;
      end
    end else begin
      mstatus_q       <= mstatus_d;
      mie_q           <= mie_d;
      mtvec_q         <= mtvec_d;
      mscratch_q      <= mscratch_d;
      mepc_q          <= mepc_d;
      mcause_q        <= mcause_d;
      mtval_q         <= mtval_d;
      mip_q           <= mip_d;
      mcountinhibit_q <= mcountinhibit_d;
      mseccfg_q       <= mseccfg_d;
      cpuctrl_q       <= cpuctrl_d;
      dcsr_q          <= dcsr_d;
      dpc_q           <= dpc_d;
      dscratch0_q     <= dscratch0_d;
      dscratch1_q     <= dscratch1_d;
      mcycle_counter   <= mcycle_counter_d;
      minstret_counter <= minstret_counter_d;
      for (int i = 0; i < MAX_HPM_COUNTERS; i++) begin
        mhpm_counter[i] <= mhpm_counter_d[i];
        mhpm_event[i]   <= mhpm_event_d[i];
      end
      for (int i = 0; i < ibex_pkg::PMP_MAX_REGIONS; i++) begin
        pmpcfg[i]  <= pmpcfg_d[i];
        pmpaddr[i] <= pmpaddr_d[i];
      end
    end
  end

  // =========================================================================
  // Output assignments
  // =========================================================================
  assign priv_mode_id_o  = IbexMuBiOn;
  assign priv_mode_lsu_o = IbexMuBiOn;
  assign csr_mtvec_o = mtvec_q;
  assign csr_mstatus_mie_o = mstatus_q[3];
  assign csr_mstatus_tw_o  = mstatus_q[21];
  assign csr_mepc_o  = mepc_q;
  assign csr_mtval_o = mtval_q;
  assign csr_depc_o  = dpc_q;
  assign irq_pending_o = (mie_q & mip_q) != 32'h0;
  assign irqs_o.irq_software = irq_software_i;
  assign irqs_o.irq_timer    = irq_timer_i;
  assign irqs_o.irq_external = irq_external_i;
  assign irqs_o.irq_fast     = irq_fast_i;
  assign irqs_o.irq_nm       = nmi_mode_i;
  assign data_ind_timing_o     = cpuctrl_q[1];
  assign dummy_instr_en_o      = cpuctrl_q[2];
  assign dummy_instr_mask_o    = 3'b111;
  assign dummy_instr_seed_en_o = cpuctrl_q[2];
  assign dummy_instr_seed_o    = 32'h0;
  assign icache_enable_o       = cpuctrl_q[0];
  assign csr_shadow_err_o  = 1'b0;
  assign debug_single_step_o = 1'b0;
  assign debug_ebreakm_o   = 1'b0;
  assign debug_ebreaku_o   = 1'b0;
  assign trigger_match_o   = 1'b0;
  assign double_fault_seen_o = 1'b0;
  for (genvar i = 0; i < ibex_pkg::PMP_MAX_REGIONS; i++) begin : g_pmp_out
    assign csr_pmp_cfg_o[i] = pmpcfg[i];
    assign csr_pmp_addr_o[i] = pmpaddr[i];
  end
  assign csr_pmp_mseccfg_o = mseccfg_q;

endmodule
